  className,
  frame,
  fillHeight,
  zoom,
  children,
}: {
  className?: string;
  frame: boolean;
  fillHeight: boolean;
  zoom: number;
  children: React.ReactNode;
}) {
  return (
    <div
      data-slot="csv-viewer"
      className={cn(
        "bg-card flex flex-col overflow-hidden",
        frame && "rounded-xl border",
        fillHeight && "h-full min-h-0 flex-1",
        className,
      )}
      style={{ fontSize: CSV_VIEWER_BASE_FONT_SIZE * zoom }}
