    cellAddress: CsvCellAddress,
    options?: { behavior?: ScrollBehavior },
  ) => void;
  getViewportElement: () => HTMLDivElement | null;
}

export interface CsvGridProps {
  columns: string[];
  rowStore: CsvRowStore;
  activeCell: CsvCellAddress | null;
  height: number;
  fillHeight: boolean;
  isolateStyles: boolean;
  scale: number;
  sortResetKey: unknown;
  statusNode: React.ReactNode;
}

const CSV_TABLE_LABEL = "CSV data";
const COLUMN_WIDTH = 180;
const COLUMN_OVERSCAN = 2;
const JUMP_COLUMN_OVERSCAN = 0;
const ROW_HEIGHT = 33;
const ROW_NUMBER_WIDTH = 56;
const ROW_OVERSCAN = 4;
const JUMP_ROW_OVERSCAN = 0;
const SMALL_TABLE_ROW_LIMIT = 200;
const SMALL_TABLE_COLUMN_LIMIT = 8;
const WORKER_SORT_ROW_THRESHOLD = 20_000;
const CSV_NATIVE_FIND_MAX_INDEXED_CELLS = 1_000_000;

export const CsvGrid = React.forwardRef<CsvGridHandle, CsvGridProps>(
  function CsvGrid(
    {
      columns,
      rowStore,
      activeCell,
      height,
      fillHeight,
      isolateStyles,
      scale,
      sortResetKey,
      statusNode,
    },
    ref,
  ) {
    const [sort, setSort] = React.useState<{
      columnIndex: number;
      descending: boolean;
    } | null>(null);
    const columnShapeKey = React.useMemo(
      () => columns.join("\u0000"),
      [columns],
    );

    useKeyedMountEffect(
      joinEffectKey(["csv-sort-reset", columnShapeKey, sortResetKey]),
      () => {
        setSort(null);
      },
    );

    const toggleSort = React.useCallback((columnIndex: number) => {
      setSort((current) =>
        !current || current.columnIndex !== columnIndex
          ? { columnIndex, descending: false }
          : current.descending
            ? null
            : { columnIndex, descending: true },
      );
    }, []);

    const rowOrder = useCsvSortedRowOrder({ rowStore, sort });

    const displayIndexByRowIndex = React.useMemo<Map<
      number,
      number
    > | null>(() => {
      if (!rowOrder) return null;
      const map = new Map<number, number>();
      rowOrder.forEach((rowIndex, displayRowIndex) => {
        map.set(rowIndex, displayRowIndex);
      });
      return map;
    }, [rowOrder]);

    const rowAt = React.useCallback(
      (displayRowIndex: number): Row => {
        const sourceRowIndex = rowOrder?.[displayRowIndex] ?? displayRowIndex;
        return rowStore.getRow(sourceRowIndex);
      },
      [rowStore, rowOrder],
    );

    const rowIndexAt = React.useCallback(
      (displayRowIndex: number): number =>
        rowOrder?.[displayRowIndex] ?? displayRowIndex,
      [rowOrder],
    );

    const viewportRef = React.useRef<HTMLDivElement>(null);
    const rowOffsetRef = React.useRef<HTMLDivElement>(null);
    const rowWindowRef = React.useRef<HTMLDivElement>(null);
    const [viewportElement, setViewportElement] =
      React.useState<HTMLDivElement | null>(null);
    const setViewportRef = React.useCallback((node: HTMLDivElement | null) => {
      viewportRef.current = node;
      setViewportElement((current) => (current === node ? current : node));
    }, []);
    const columnCount = columns.length;
    const rowCount = rowStore.rowCount;
    const columnOffset = 1;
    const shouldVirtualizeRows = rowCount > SMALL_TABLE_ROW_LIMIT;
    const shouldVirtualizeColumns = columnCount > SMALL_TABLE_COLUMN_LIMIT;
    const effectiveRowHeight = Math.max(1, Math.round(ROW_HEIGHT * scale));
    const effectiveColumnWidth = Math.max(1, Math.round(COLUMN_WIDTH * scale));
    const effectiveRowNumberWidth = Math.round(ROW_NUMBER_WIDTH * scale);
    const columnItemsRef = React.useRef<FixedGridColumnItem[]>([]);
    const viewportClientHeightRef = React.useRef(0);
    const getRowPatchState = React.useCallback(
      (): CsvRowPatchState => ({
        activeCell: activeCell ?? null,
        columnItems: columnItemsRef.current,
        effectiveRowHeight,
        viewportHeight: viewportClientHeightRef.current,
        rowStore,
        rowOrder,
        shouldVirtualizeRows,
      }),
      [
        activeCell,
        effectiveRowHeight,
        rowStore,
        rowOrder,
        shouldVirtualizeRows,
      ],
    );
    const rowPatcher = useCsvRowPatcher({
      rowOffsetRef,
      rowWindowRef,
      getState: getRowPatchState,
    });
    const rowScrollStrategy = React.useMemo(
      () => ({ handleViewport: rowPatcher.patch }),
      [rowPatcher],
    );

    const {
      virtualRows,
      totalRowSize,
      totalColumnSize,
      columnItems,
      virtualRowWindow,
      leftPad,
      rightPad,
      scrollToCell,
      viewportClientHeight,
    } = useFixedGridVirtualization({
      rowCount,
      columnCount,
      rowSize: effectiveRowHeight,
      columnSize: effectiveColumnWidth,
      rowOverscan: ROW_OVERSCAN,
      columnOverscan: COLUMN_OVERSCAN,
      jumpRowOverscan: JUMP_ROW_OVERSCAN,
      jumpColumnOverscan: JUMP_COLUMN_OVERSCAN,
      minimumRenderedRows: 1,
      rowScrollStrategy,
      scrollRef: viewportRef,
      scrollElement: viewportElement,
      virtualizeColumns: shouldVirtualizeColumns,
    });

    columnItemsRef.current = columnItems;
    viewportClientHeightRef.current = viewportClientHeight;

    React.useImperativeHandle(
      ref ?? null,
      () => ({
        scrollToCell: (cellAddress, options) => {
          const behavior = options?.behavior ?? "smooth";
          const displayRowIndex =
            displayIndexByRowIndex?.get(cellAddress.rowIndex) ??
            cellAddress.rowIndex;
          scrollToCell({
            rowIndex: displayRowIndex,
            columnIndex: cellAddress.columnIndex,
            behavior,
            align: "center",
          });
        },
        getViewportElement: () => viewportRef.current,
      }),
      [displayIndexByRowIndex, scrollToCell],
    );

    const gridTemplate = React.useMemo(
      () =>
        buildVirtualGridTemplate({
          leadingWidth: effectiveRowNumberWidth,
          leftPad,
          columnWidths: fixedGridColumnWidths(columnItems),
          rightPad,
        }),
      [effectiveRowNumberWidth, leftPad, columnItems, rightPad],
    );
    const totalWidth = effectiveRowNumberWidth + totalColumnSize;
    const minimumRowPoolSize =
      Math.ceil(viewportClientHeight / effectiveRowHeight) +
      ROW_OVERSCAN * 2 +
      2;
    const rowPoolSlots = useFixedRowPool({
      minimumPoolSize: minimumRowPoolSize,
      rowCount,
      virtualRows: virtualRowWindow.items,
    });
    const shouldIndexNativeFind =
      rowCount > 0 &&
      columnCount > 0 &&
      (shouldVirtualizeRows || shouldVirtualizeColumns);
    const nativeFindCellText = React.useCallback(
      (displayRowIndex: number, columnIndex: number) =>
        rowAt(displayRowIndex)?.[columnIndex] ?? "",
      [rowAt],
    );
    const scrollToNativeFindCell = React.useCallback(
      ({ rowIndex, columnIndex }: FixedGridNativeFindCellAddress) => {
        scrollToCell({
          rowIndex,
          columnIndex,
          behavior: "auto",
          align: "center",
        });
      },
      [scrollToCell],
    );

    useKeyedMountEffect(
      joinEffectKey([
        "csv-row-patcher",
        rowPatcher,
        virtualRows,
        columnItems,
        shouldVirtualizeRows,
      ]),
      () => {
        // After React commits the canonical row window, push that window's
        // visibility, position, and text back onto the pooled DOM so any stale
        // state left by the imperative scroll patcher (a `hidden` row React's
        // reconciler never re-showed, or a cyclic-column cell it never rewrote)
        // is cleared. Falls back to a plain cache invalidation when row
        // virtualization is inactive.
        if (shouldVirtualizeRows) {
          rowPatcher.resync(virtualRows);
        } else {
          rowPatcher.invalidate();
        }
      },
    );

    return (
      <div
        data-slot="csv-grid"
        role="table"
        aria-label={CSV_TABLE_LABEL}
        aria-rowcount={rowCount + 1}
        aria-colcount={columnCount + columnOffset}
        className={cn("relative", fillHeight && "min-h-0 flex-1")}
      >
        <CsvStyleScope
          isolate={isolateStyles}
          className={cn("relative", fillHeight && "h-full min-h-0")}
          style={fillHeight ? undefined : { height, maxHeight: "100%" }}
        >
          <style>{CSV_SCROLLBAR_CSS}</style>
          <FixedGridNativeFindIndex
            rowCount={rowCount}
            columnCount={columnCount}
            getCellText={nativeFindCellText}
            onCellMatch={scrollToNativeFindCell}
            dataSlot="csv-native-find-index"
            enabled={shouldIndexNativeFind}
            maxIndexedCells={CSV_NATIVE_FIND_MAX_INDEXED_CELLS}
          />
          <FixedGridViewport scrollRef={setViewportRef} dataSlot="csv-body">
            <div
              style={getFixedGridCanvasStyle({
                width: totalWidth,
                contain: true,
              })}
            >
              <div
                role="row"
                aria-rowindex={1}
                data-slot="csv-header"
                className="sticky top-0 z-20 grid border-b"
                style={{
                  gridTemplateColumns: gridTemplate,
                  backgroundColor:
                    "color-mix(in oklab, var(--card) 92%, var(--foreground))",
                }}
              >
                <div
                  role="columnheader"
                  aria-colindex={1}
                  aria-label="Row number"
                  className="sticky left-0 z-10 border-r bg-[color-mix(in_oklab,var(--card)_94%,var(--foreground))]"
                  style={{ height: effectiveRowHeight }}
                />
                <Spacer width={leftPad} />
                {columnItems.map((item) => (
                  <HeaderCell
                    key={item.index}
                    name={columns[item.index] || `Column ${item.index + 1}`}
                    columnIndex={columnOffset + item.index + 1}
                    height={effectiveRowHeight}
                    sorted={
                      sort?.columnIndex === item.index
                        ? sort.descending
                          ? "desc"
                          : "asc"
                        : false
                    }
                    onToggle={() => toggleSort(item.index)}
                  />
                ))}
                <Spacer width={rightPad} />
              </div>

              {statusNode ? (
                statusNode
              ) : shouldVirtualizeRows ? (
                <FixedGridRowWindow
                  role="rowgroup"
                  rowOffsetRef={rowOffsetRef}
                  rowWindowRef={rowWindowRef}
                  totalSize={totalRowSize}
                  virtualRowWindow={virtualRowWindow}
                  viewportHeight={viewportClientHeight}
                  offsetDataSlot="csv-row-offset"
                  windowDataSlot="csv-row-window"
                >
                  {rowPoolSlots.map((slot) => (
                    <CsvRowSlot
                      key={slot.slotIndex}
                      slot={slot}
                      sourceRowCount={rowCount}
                      rowAt={rowAt}
                      rowIndexAt={rowIndexAt}
                      gridTemplate={gridTemplate}
                      rowHeight={effectiveRowHeight}
                      columnOffset={columnOffset}
                      columnItems={columnItems}
                      leftPad={leftPad}
                      rightPad={rightPad}
                      activeCell={activeCell}
                    />
                  ))}
                </FixedGridRowWindow>
              ) : (
                <div role="rowgroup">
                  {Array.from({ length: rowCount }, (_, displayRowIndex) => (
                    <CsvRow
                      key={displayRowIndex}
                      cells={rowAt(displayRowIndex)}
                      displayRowIndex={displayRowIndex}
                      rowIndex={rowIndexAt(displayRowIndex)}
                      gridTemplate={gridTemplate}
                      rowHeight={effectiveRowHeight}
                      columnOffset={columnOffset}
                      columnItems={columnItems}
                      leftPad={leftPad}
                      rightPad={rightPad}
                      activeColumnIndex={
                        activeCell?.rowIndex === rowIndexAt(displayRowIndex)
                          ? activeCell.columnIndex
                          : null
                      }
                    />
                  ))}
                </div>
              )}
            </div>
          </FixedGridViewport>
          <HeaderAwareScrollbar
            scrollRef={viewportRef}
            headerHeight={effectiveRowHeight}
          />
        </CsvStyleScope>
      </div>
    );
  },
);

function useCsvSortedRowOrder({
  rowStore,
  sort,
}: {
  rowStore: CsvRowStore;
  sort: { columnIndex: number; descending: boolean } | null;
}): number[] | null {
  const [workerRowOrder, setWorkerRowOrder] = React.useState<number[] | null>(
    null,
  );
  const sourceRows = React.useMemo(
    () => (sort ? rowStore.materializeRows() : null),
    [rowStore, sort],
  );
  const shouldUseWorker =
    !!sort &&
    !!sourceRows &&
    sourceRows.length >= WORKER_SORT_ROW_THRESHOLD &&
    typeof Worker !== "undefined";

  const workerSortKey =
    sort && sourceRows && shouldUseWorker
      ? joinEffectKey(["csv-worker-sort", shouldUseWorker, sort, sourceRows])
      : null;
  useKeyedMountEffect(workerSortKey, () => {
    if (!sort || !sourceRows || !shouldUseWorker) {
      setWorkerRowOrder(null);
      return;
    }
    setWorkerRowOrder(null);

    const controller = new AbortController();
    void sortCsvRowsInWorker({
      sourceRows,
      columnIndex: sort.columnIndex,
      descending: sort.descending,
      signal: controller.signal,
    }).then(
      (rowOrder) => setWorkerRowOrder(rowOrder),
      (error) => {
        if (controller.signal.aborted) return;
        setWorkerRowOrder(
          sortCsvRowsOnMainThread({
            sourceRows,
            columnIndex: sort.columnIndex,
            descending: sort.descending,
          }),
        );
      },
    );

    return () => controller.abort();
  });

  return React.useMemo(() => {
    if (!sort || !sourceRows) return null;
    if (shouldUseWorker) return workerRowOrder;
    return sortCsvRowsOnMainThread({
      sourceRows,
      columnIndex: sort.columnIndex,
      descending: sort.descending,
    });
  }, [shouldUseWorker, sort, sourceRows, workerRowOrder]);
}

function Spacer({ width }: { width: number }) {
  return <div role="presentation" aria-hidden style={{ width }} />;
}

function HeaderCell({
  name,
  columnIndex,
  height,
  sorted,
  onToggle,
}: {
  name: string;
  columnIndex: number;
  height: number;
  sorted: "asc" | "desc" | false;
  onToggle: () => void;
}) {
  return (
    <div
      role="columnheader"
      aria-colindex={columnIndex}
      aria-sort={
        sorted === "asc"
          ? "ascending"
          : sorted === "desc"
            ? "descending"
            : "none"
      }
      data-slot="csv-header-cell"
      className="border-r last:border-r-0"
    >
      <button
        type="button"
        onClick={onToggle}
        className="text-muted-foreground hover:bg-muted hover:text-foreground focus-visible:bg-muted flex w-full items-center gap-1 px-3 text-left font-medium transition-colors focus-visible:outline-none"
        style={{ height }}
        title={`Sort by ${name}`}
      >
        <span className="truncate">{name}</span>
        {sorted ? (
          sorted === "asc" ? (
            <ChevronUp
              className="text-muted-foreground size-3.5 shrink-0"
              aria-hidden
            />
          ) : (
            <ChevronDown
              className="text-muted-foreground size-3.5 shrink-0"
              aria-hidden
            />
          )
        ) : null}
      </button>
    </div>
  );
}

function CsvRowSlot({
  slot,
  sourceRowCount,
  rowAt,
  rowIndexAt,
  gridTemplate,
  rowHeight,
  columnOffset,
  columnItems,
  leftPad,
  rightPad,
  activeCell,
}: {
  slot: FixedGridRowPoolSlot;
  sourceRowCount: number;
  rowAt: (displayRowIndex: number) => Row;
  rowIndexAt: (displayRowIndex: number) => number;
  gridTemplate: string;
  rowHeight: number;
  columnOffset: number;
  columnItems: FixedGridColumnItem[];
  leftPad: number;
  rightPad: number;
  activeCell: CsvCellAddress | null;
}) {
  const fallbackDisplayRowIndex =
    sourceRowCount > 0 ? Math.min(slot.slotIndex, sourceRowCount - 1) : 0;
  const displayRowIndex = slot.virtualRow?.index ?? fallbackDisplayRowIndex;
  const rowIndex = rowIndexAt(displayRowIndex);

  return (
    <CsvRow
      cells={rowAt(displayRowIndex)}
      displayRowIndex={displayRowIndex}
      rowIndex={rowIndex}
      gridTemplate={gridTemplate}
      rowHeight={rowHeight}
      columnOffset={columnOffset}
      columnItems={columnItems}
      leftPad={leftPad}
      rightPad={rightPad}
      start={slot.virtualRow?.start ?? 0}
      hidden={slot.isHidden}
      activeColumnIndex={
        slot.virtualRow && activeCell?.rowIndex === rowIndex
          ? activeCell.columnIndex
          : null
      }
    />
  );
}

const CsvRow = React.memo(function CsvRow({
  cells,
  displayRowIndex,
  rowIndex,
  gridTemplate,
  rowHeight,
  columnOffset,
  columnItems,
  leftPad,
  rightPad,
  start,
  hidden = false,
  activeColumnIndex,
}: {
  cells: Row | undefined;
  displayRowIndex: number;
  rowIndex: number;
  gridTemplate: string;
  rowHeight: number;
  columnOffset: number;
  columnItems: FixedGridColumnItem[];
  leftPad: number;
  rightPad: number;
  start?: number;
  hidden?: boolean;
  activeColumnIndex?: number | null;
}) {
  const isVirtualized = start !== undefined;
  const style: React.CSSProperties = !isVirtualized
    ? { gridTemplateColumns: gridTemplate, height: rowHeight }
    : getFixedGridRowStyle({
        gridTemplate,
        rowHeight,
        top: start,
      });
  return (
    <div
      role="row"
      aria-rowindex={displayRowIndex + 2}
      hidden={hidden}
      data-slot="csv-row"
      className={cn(
        "grid border-b",
        !isVirtualized && "group hover:bg-muted/40",
      )}
      style={style}
    >
      <div
        role="rowheader"
        aria-colindex={1}
        data-slot="csv-row-number"
        className={cn(
          "bg-card text-muted-foreground sticky left-0 z-[1] flex items-center justify-end border-r px-2 tabular-nums",
          !isVirtualized &&
            "group-hover:bg-[color-mix(in_oklab,var(--card)_97%,var(--foreground))]",
        )}
      >
        {rowIndex + 1}
      </div>
      <Spacer width={leftPad} />
      {columnItems.map((item) => {
        const text = cells?.[item.index] ?? "";
        const isActive = activeColumnIndex === item.index;
        return (
          <div
            key={item.index}
            role="cell"
            aria-colindex={columnOffset + item.index + 1}
            data-slot="csv-cell"
            className={csvCellClassName(isActive)}
            title={isVirtualized ? undefined : text}
          >
            <span className="truncate">{text}</span>
          </div>
        );
      })}
      <Spacer width={rightPad} />
    </div>
  );
});

"use client";

import * as React from "react";

import type { CsvCellAddress } from "./csv-viewer-state";
import { csvCellClassName } from "./csv-viewer-cell-classes";
import type { CsvRowStore } from "./csv-row-store";
import { setFixedGridInverseRowWindowGeometry } from "./fixed-grid-layout";
import {
  fixedVirtualItemWindow,
  fixedVirtualItems,
  type FixedGridColumnItem,
  type FixedGridJumpViewportResult,
  type FixedGridViewport,
  type FixedGridVirtualItem,
} from "./fixed-grid-virtualization";

export interface CsvRowPatchState {
  activeCell: CsvCellAddress | null;
  columnItems: FixedGridColumnItem[];
  effectiveRowHeight: number;
  viewportHeight: number;
  rowOrder: number[] | null;
  shouldVirtualizeRows: boolean;
  rowStore: CsvRowStore;
}

export interface CsvRowPatcher {
  patch: (viewport: FixedGridViewport) => FixedGridJumpViewportResult;
  resync: (virtualRows: FixedGridVirtualItem[]) => void;
  invalidate: () => void;
}

interface CsvCellHandle {
  element: HTMLElement;
  className: string;
  textNode: Text | null;
}

interface CsvRowHandle {
  element: HTMLElement;
  rowNumberTextNode: Text | null;
  cells: CsvCellHandle[];
  isHidden: boolean;
  sourceRowIndex: number | null;
  transform: string;
}

interface CsvRowHandleCache {
  rowWindow: HTMLDivElement;
  rows: CsvRowHandle[];
}

const PATCH_ROW_OVERSCAN = 0;
const MINIMUM_PATCH_VISIBLE_ROWS = 1;
const TEXT_NODE = 3;

export function useCsvRowPatcher({
  rowOffsetRef,
  rowWindowRef,
  getState,
}: {
  rowOffsetRef: React.RefObject<HTMLDivElement | null>;
  rowWindowRef: React.RefObject<HTMLDivElement | null>;
  getState: () => CsvRowPatchState;
}): CsvRowPatcher {
  const rowHandleCacheRef = React.useRef<CsvRowHandleCache | null>(null);

  const invalidate = React.useCallback(() => {
    rowHandleCacheRef.current = null;
  }, []);

  // Re-assert the canonical (React-owned) row state onto every pooled row after
  // a canonical commit. During active scroll the imperative patcher mutates
  // each row's `hidden` attribute, transform, row number, and cell text
  // directly. When React later commits a window, its reconciler only writes a
  // DOM property whose value changed in React's *own* remembered vdom, so a
  // reused slot whose canonical value is unchanged across the commit keeps
  // whatever the patcher last wrote. That leaks two ways: a previously-hidden
  // pool row that should now be visible stays `hidden` (a blank gap at the
  // leading scroll edge), and a cyclic column (e.g. a repeating name) keeps a
  // stale value from a different row even though its id and row number are
  // correct. Re-running the canonical window through the same patch routine
  // pushes the authoritative transform, visibility, and text back onto the DOM
  // once scrolling settles. This runs only on canonical commits, not per frame.
  const resync = React.useCallback(
    (virtualRows: FixedGridVirtualItem[]) => {
      const rowWindow = rowWindowRef.current;
      if (!rowWindow) return;
      const rowOffset = rowOffsetRef.current;
      if (!rowOffset) return;
      const cache = readRowHandles(rowWindow);
      rowHandleCacheRef.current = cache;
      if (cache.rows.length === 0) return;
      const state = getState();
      const window = fixedVirtualItemWindow(virtualRows);
      setFixedGridInverseRowWindowGeometry({
        rowOffsetElement: rowOffset,
        rowWindowElement: rowWindow,
        viewportHeight: state.viewportHeight,
        window,
      });
      patchRows(cache.rows, window.items, state);
    },
    [getState, rowOffsetRef, rowWindowRef],
  );

  const patch = React.useCallback(
    (viewport: FixedGridViewport): FixedGridJumpViewportResult => {
      const state = getState();
      if (!canPatchRows(viewport, state)) return "pass";

      const rowWindow = rowWindowRef.current;
      if (!rowWindow) return "pass";
      const rowOffset = rowOffsetRef.current;
      if (!rowOffset) return "pass";

      const cache =
        rowHandleCacheRef.current?.rowWindow === rowWindow
          ? rowHandleCacheRef.current
          : readRowHandles(rowWindow);
      rowHandleCacheRef.current = cache;

      if (cache.rows.length === 0) return "pass";

      const nextRows = fixedVirtualItems({
        count: state.rowStore.rowCount,
        size: state.effectiveRowHeight,
        scrollOffset: viewport.scrollTop,
        viewportSize: viewport.clientHeight,
        overscan: PATCH_ROW_OVERSCAN,
        minimumVisibleCount: MINIMUM_PATCH_VISIBLE_ROWS,
      });
      if (nextRows.length === 0 || nextRows.length > cache.rows.length) {
        return "pass";
      }

      if (
        !canPatchRowHandles(
          cache.rows,
          nextRows.length,
          state.columnItems.length,
        )
      ) {
        return "pass";
      }

      const window = fixedVirtualItemWindow(nextRows);
      setFixedGridInverseRowWindowGeometry({
        rowOffsetElement: rowOffset,
        rowWindowElement: rowWindow,
        viewportHeight: viewport.clientHeight,
        window,
      });
      patchRows(cache.rows, window.items, state);

      return "handled";
    },
    [getState, rowOffsetRef, rowWindowRef],
  );

  return React.useMemo(
    () => ({ invalidate, patch, resync }),
    [invalidate, patch, resync],
  );
}

function patchRows(
  rowHandles: CsvRowHandle[],
  virtualRows: ReturnType<typeof fixedVirtualItems>,
  state: CsvRowPatchState,
) {
  for (let handleIndex = 0; handleIndex < rowHandles.length; handleIndex++) {
    const rowHandle = rowHandles[handleIndex];
    const virtualRow = virtualRows[handleIndex];
    if (!virtualRow) {
      setRowHidden(rowHandle, true);
      continue;
    }

    const displayRowIndex = virtualRow.index;
    const sourceRowIndex = state.rowOrder
      ? state.rowOrder[displayRowIndex]
      : displayRowIndex;
    const sourceRow = state.rowStore.getRow(sourceRowIndex);
    const transform = `translate3d(0, ${virtualRow.start}px, 0)`;

    setRowHidden(rowHandle, false);
    setRowTransform(rowHandle, transform);

    if (rowHandle.sourceRowIndex !== sourceRowIndex) {
      rowHandle.sourceRowIndex = sourceRowIndex;
      setTextNodeValue(rowHandle.rowNumberTextNode, String(sourceRowIndex + 1));
      patchCells(rowHandle, sourceRow, sourceRowIndex, state);
    } else {
      patchCellActiveState(rowHandle, sourceRowIndex, state);
    }
  }
}

function patchCells(
  rowHandle: CsvRowHandle,
  sourceRow: string[] | undefined,
  sourceRowIndex: number,
  state: CsvRowPatchState,
) {
  for (let cellIndex = 0; cellIndex < state.columnItems.length; cellIndex++) {
    const columnIndex = state.columnItems[cellIndex]?.index;
    const text =
      typeof columnIndex === "number" ? (sourceRow?.[columnIndex] ?? "") : "";
    setTextNodeValue(rowHandle.cells[cellIndex]?.textNode ?? null, text);
    setCellActive(
      rowHandle.cells[cellIndex],
      state.activeCell?.rowIndex === sourceRowIndex &&
        state.activeCell.columnIndex === columnIndex,
    );
  }
}

function patchCellActiveState(
  rowHandle: CsvRowHandle,
  sourceRowIndex: number,
  state: CsvRowPatchState,
) {
  for (let cellIndex = 0; cellIndex < state.columnItems.length; cellIndex++) {
    const columnIndex = state.columnItems[cellIndex]?.index;
    setCellActive(
      rowHandle.cells[cellIndex],
      state.activeCell?.rowIndex === sourceRowIndex &&
        state.activeCell.columnIndex === columnIndex,
    );
  }
}

function canPatchRows(viewport: FixedGridViewport, state: CsvRowPatchState) {
  return state.shouldVirtualizeRows && !viewport.isJumpingColumns;
}

function canPatchRowHandles(
  rowHandles: CsvRowHandle[],
  visibleRowCount: number,
  cellCount: number,
) {
  for (let handleIndex = 0; handleIndex < visibleRowCount; handleIndex++) {
    const rowHandle = rowHandles[handleIndex];
    if (!rowHandle?.rowNumberTextNode) return false;
    for (let cellIndex = 0; cellIndex < cellCount; cellIndex++) {
      if (!rowHandle.cells[cellIndex]?.textNode) return false;
    }
  }
  return true;
}

function readRowHandles(rowWindow: HTMLDivElement): CsvRowHandleCache {
  const rows = Array.from(
    rowWindow.querySelectorAll<HTMLElement>('[data-slot="csv-row"]'),
  ).map((element) => {
    const rowNumber = element.querySelector<HTMLElement>(
      '[data-slot="csv-row-number"]',
    );
    const cells = Array.from(
      element.querySelectorAll<HTMLElement>('[data-slot="csv-cell"]'),
    ).map((cell) => ({
      element: cell,
      className: cell.className,
      textNode: firstTextNode(cell.firstElementChild ?? cell),
    }));

    return {
      element,
      rowNumberTextNode: firstTextNode(rowNumber),
      cells,
      isHidden: element.hidden,
      sourceRowIndex: null,
      transform: element.style.transform,
    };
  });

  return { rowWindow, rows };
}

function firstTextNode(element: Element | null): Text | null {
  const node = element?.firstChild;
  return node?.nodeType === TEXT_NODE ? (node as Text) : null;
}

function setTextNodeValue(textNode: Text | null, value: string) {
  if (textNode && textNode.nodeValue !== value) textNode.nodeValue = value;
}

function setCellActive(cell: CsvCellHandle | undefined, isActive: boolean) {
  if (!cell) return;
  const className = csvCellClassName(isActive);
  if (cell.className === className) return;
  cell.element.className = className;
  cell.className = className;
}

function setRowTransform(row: CsvRowHandle, transform: string) {
  if (row.transform === transform) return;
  row.element.style.transform = transform;
  row.transform = transform;
}

function setRowHidden(row: CsvRowHandle, isHidden: boolean) {
  if (row.isHidden === isHidden) return;
  row.element.hidden = isHidden;
  row.isHidden = isHidden;
}

export const CSV_CELL_CLASS =
  "flex items-center truncate border-r px-3 last:border-r-0";

export const CSV_ACTIVE_CELL_CLASS =
  "bg-primary/12 ring-1 ring-primary/50 ring-offset-0 ring-inset";

export function csvCellClassName(isActive: boolean): string {
  return isActive
    ? `${CSV_CELL_CLASS} ${CSV_ACTIVE_CELL_CLASS}`
    : CSV_CELL_CLASS;
}

export interface CsvRowStore {
  readonly rowCount: number;
  readonly version: number;
  getRow(index: number): string[] | undefined;
  materializeRows(): string[][];
}

export interface MutableCsvRowStore {
  appendRows(rows: string[][]): void;
  padRowsToColumnCount(columnCount: number): void;
  snapshot(): CsvRowStore;
  materializeRows(): string[][];
}

const EMPTY_CSV_ROW_STORE = createCsvRowStoreFromRows([]);

export function emptyCsvRowStore(): CsvRowStore {
  return EMPTY_CSV_ROW_STORE;
}

export function createCsvRowStoreFromRows(rows: string[][]): CsvRowStore {
  return {
    rowCount: rows.length,
    version: 0,
    getRow: (index) => rows[index],
    materializeRows: () => rows,
  };
}

export function createMutableCsvRowStore(): MutableCsvRowStore {
  const chunks: string[][][] = [];
  const starts: number[] = [];
  let rowCount = 0;
  let version = 0;

  function appendRows(rows: string[][]) {
    if (rows.length === 0) return;
    starts.push(rowCount);
    chunks.push(rows);
    rowCount += rows.length;
    version += 1;
  }

  function padRowsToColumnCount(columnCount: number) {
    for (const chunk of chunks) {
      for (const row of chunk) {
        while (row.length < columnCount) row.push("");
      }
    }
    version += 1;
  }

  function getRow(index: number): string[] | undefined {
    if (!Number.isSafeInteger(index) || index < 0 || index >= rowCount) {
      return undefined;
    }
    const chunkIndex = findChunkIndex(starts, index);
    const chunk = chunks[chunkIndex];
    return chunk?.[index - starts[chunkIndex]];
  }

  function materializeRows(): string[][] {
    return chunks.flat();
  }

  function snapshot(): CsvRowStore {
    const snapshotVersion = version;
    const snapshotRowCount = rowCount;
    return {
      rowCount: snapshotRowCount,
      version: snapshotVersion,
      getRow,
      materializeRows,
    };
  }

  return {
    appendRows,
    padRowsToColumnCount,
    snapshot,
    materializeRows,
  };
}

function findChunkIndex(starts: number[], rowIndex: number): number {
  let low = 0;
  let high = starts.length - 1;
  while (low <= high) {
    const mid = Math.floor((low + high) / 2);
    const start = starts[mid];
    const nextStart = starts[mid + 1] ?? Number.POSITIVE_INFINITY;
    if (rowIndex < start) {
      high = mid - 1;
    } else if (rowIndex >= nextStart) {
      low = mid + 1;
    } else {
      return mid;
    }
  }
  return 0;
}

/**
 * Sorting helpers for the CSV grid.
 *
 * Cells are plain strings, but a column is often numeric (or mostly numeric
 * with a few text outliers). `compareCsvCells` keeps numeric-looking values in
 * numeric order while still producing a *total order* over mixed values: all
 * numeric cells sort together (ahead of text), and text cells sort
 * lexicographically. A total order matters because `Array.prototype.sort`
 * requires a consistent comparator — a comparator that is numeric for some
 * pairs and lexicographic for others can be intransitive, which makes the
 * displayed order depend on the original row order.
 */

/** A value is treated as numeric when `Number()` yields a finite-ish number. */
export function isNumericCell(value: string): boolean {
  return value !== "" && !Number.isNaN(Number(value));
}

export function compareCsvCells(a: string, b: string): number {
  const aNumeric = isNumericCell(a);
  const bNumeric = isNumericCell(b);
  if (aNumeric && bNumeric) {
    const diff = Number(a) - Number(b);
    return diff < 0 ? -1 : diff > 0 ? 1 : 0;
  }
  // Numeric cells always sort ahead of text cells so the comparator stays a
  // total order regardless of which pairs are being compared.
  if (aNumeric) return -1;
  if (bNumeric) return 1;
  return a < b ? -1 : a > b ? 1 : 0;
}

export type CsvSortKey =
  | {
      kind: "number";
      value: number;
      rowIndex: number;
    }
  | {
      kind: "text";
      value: string;
      rowIndex: number;
    };

/**
 * Returns the display order (source-row indices) for a column sort. Ascending
 * order follows `compareCsvCells`; descending negates it. Rows that compare
 * equal always keep their original relative order in *both* directions: a
 * naive `reverse()` of the ascending order would flip tied rows, so equal keys
 * fall back to the source index as a stable tiebreaker.
 */
export function sortedRowOrder(
  sourceRows: string[][],
  columnIndex: number,
  descending: boolean,
): number[] {
  return sortedRowOrderFromKeys(
    sourceRows.map((row, rowIndex) =>
      csvSortKey(row[columnIndex] ?? "", rowIndex),
    ),
    descending,
  );
}

export function csvSortKey(value: string, rowIndex: number): CsvSortKey {
  if (isNumericCell(value)) {
    return {
      kind: "number",
      value: Number(value),
      rowIndex,
    };
  }
  return {
    kind: "text",
    value,
    rowIndex,
  };
}

export function sortedRowOrderFromKeys(
  keys: CsvSortKey[],
  descending: boolean,
): number[] {
  const orderedKeys = keys.slice();
  const direction = descending ? -1 : 1;
  orderedKeys.sort((a, b) => {
    const cmp = compareCsvSortKeys(a, b);
    return cmp !== 0 ? direction * cmp : a.rowIndex - b.rowIndex;
  });
  return orderedKeys.map((key) => key.rowIndex);
}

function compareCsvSortKeys(a: CsvSortKey, b: CsvSortKey): number {
  if (a.kind === "number" && b.kind === "number") {
    const diff = a.value - b.value;
    return diff < 0 ? -1 : diff > 0 ? 1 : 0;
  }
  if (a.kind === "number") return -1;
  if (b.kind === "number") return 1;
  return a.value < b.value ? -1 : a.value > b.value ? 1 : 0;
}

import { sortedRowOrder } from "./csv-viewer-sort";

export class CsvSortWorkerUnavailableError extends Error {
  constructor(message = "CSV sort worker unavailable", options?: ErrorOptions) {
    super(message, options);
    this.name = "CsvSortWorkerUnavailableError";
  }
}

export interface CsvSortWorkerRequest {
  sortRequestId: string;
  sourceRows: string[][];
  columnIndex: number;
  descending: boolean;
}

export type CsvSortWorkerResponse =
  | { type: "rowOrder"; sortRequestId: string; rowOrder: number[] }
  | { type: "error"; sortRequestId: string; message: string };

export function createCsvSortWorker(): Worker {
  return new Worker(new URL("./csv-viewer-sort.worker.ts", import.meta.url), {
    type: "module",
  });
}

export function sortCsvRowsInWorker({
  sourceRows,
  columnIndex,
  descending,
  signal,
}: {
  sourceRows: string[][];
  columnIndex: number;
  descending: boolean;
  signal: AbortSignal;
}): Promise<number[]> {
  return new Promise((resolve, reject) => {
    let worker: Worker;
    try {
      worker = createCsvSortWorker();
    } catch (error) {
      reject(
        new CsvSortWorkerUnavailableError("CSV sort worker unavailable", {
          cause: error,
        }),
      );
      return;
    }

    const sortRequestId = crypto.randomUUID();
    const cleanup = () => {
      signal.removeEventListener("abort", abort);
      worker.terminate();
    };
    const abort = () => {
      cleanup();
      reject(new DOMException("Aborted", "AbortError"));
    };

    signal.addEventListener("abort", abort, { once: true });
    worker.onerror = (event) => {
      cleanup();
      reject(new Error(event?.message || "CSV sort worker failed."));
    };
    worker.onmessage = (event: MessageEvent<CsvSortWorkerResponse>) => {
      const message = event.data;
      if (message.sortRequestId !== sortRequestId) return;
      if (message.type === "rowOrder") {
        cleanup();
        resolve(message.rowOrder);
      } else {
        cleanup();
        reject(new Error(message.message || "CSV sort failed."));
      }
    };

    worker.postMessage({
      sortRequestId,
      sourceRows,
      columnIndex,
      descending,
    } satisfies CsvSortWorkerRequest);
  });
}

export function sortCsvRowsOnMainThread({
  sourceRows,
  columnIndex,
  descending,
}: {
  sourceRows: string[][];
  columnIndex: number;
  descending: boolean;
}): number[] {
  return sortedRowOrder(sourceRows, columnIndex, descending);
}

import type {
  CsvSortWorkerRequest,
  CsvSortWorkerResponse,
} from "./csv-viewer-sort-worker";
import { sortedRowOrder } from "./csv-viewer-sort";

function post(message: CsvSortWorkerResponse) {
  self.postMessage(message);
}

self.onmessage = (event: MessageEvent<CsvSortWorkerRequest>) => {
  const { sortRequestId, sourceRows, columnIndex, descending } = event.data;
  try {
    post({
      type: "rowOrder",
      sortRequestId,
      rowOrder: sortedRowOrder(sourceRows, columnIndex, descending),
    });
  } catch (error) {
    post({
      type: "error",
      sortRequestId,
      message: error instanceof Error ? error.message : String(error),
    });
  }
};

"use client";

import * as React from "react";
import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { useKeyedLayoutEffect } from "@/hooks/use-keyed-layout-effect";
import { joinEffectKey } from "@/lib/effect-key";

const MINIMUM_ROW_WINDOW = 32;
const INITIAL_COLUMN_WINDOW = 8;
const MAX_VIRTUAL_ITEMS = 10_000;
const MAX_EAGER_COLUMN_ITEMS = 10_000;

export interface FixedGridColumnItem {
  index: number;
  widthPx: number;
}

export interface FixedGridVirtualItem {
  index: number;
  start: number;
  size: number;
  end: number;
}

export interface FixedGridRowPoolSlot {
  slotIndex: number;
  virtualRow: FixedGridVirtualItem | null;
  isHidden: boolean;
}

export interface FixedGridVirtualItemWindow {
  end: number;
  items: FixedGridVirtualItem[];
  size: number;
  start: number;
}

export interface FixedGridScrollTarget {
  rowIndex: number;
  columnIndex: number;
  align?: "start" | "center" | "end" | "auto";
  behavior?: ScrollBehavior;
}

export interface FixedRowScrollTarget {
  rowIndex: number;
  align?: "start" | "center" | "end" | "auto";
  behavior?: ScrollBehavior;
}

export type FixedGridJumpViewportResult = "handled" | "pass";

export interface FixedGridRowScrollStrategy {
  settleAfterMs?: number;
  handleViewport: (viewport: FixedGridViewport) => FixedGridJumpViewportResult;
}

export function useFixedRowPool({
  minimumPoolSize = 0,
  rowCount,
  virtualRows,
}: {
  minimumPoolSize?: number;
  rowCount: number;
  virtualRows: FixedGridVirtualItem[];
}): FixedGridRowPoolSlot[] {
  const poolSizeRef = React.useRef(0);
  const safeRowCount = fixedItemCount(rowCount);
  const safeMinimumPoolSize = fixedItemCount(minimumPoolSize);
  const nextPoolSize = Math.min(
    safeRowCount,
    Math.max(poolSizeRef.current, virtualRows.length, safeMinimumPoolSize),
  );
  poolSizeRef.current = nextPoolSize;

  return React.useMemo(
    () =>
      Array.from({ length: nextPoolSize }, (_, slotIndex) => {
        const virtualRow = virtualRows[slotIndex] ?? null;
        return {
          slotIndex,
          virtualRow,
          isHidden: !virtualRow,
        };
      }),
    [nextPoolSize, virtualRows],
  );
}

export function useFixedGridVirtualization({
  rowCount,
  columnCount,
  rowSize,
  columnSize,
  rowOverscan,
  columnOverscan,
  jumpRowOverscan = rowOverscan,
  jumpColumnOverscan = columnOverscan,
  minimumRenderedRows = MINIMUM_ROW_WINDOW,
  rowScrollStrategy,
  scrollRef,
  scrollElement,
  virtualizeColumns = true,
}: {
  rowCount: number;
  columnCount: number;
  rowSize: number;
  columnSize: number;
  rowOverscan: number;
  columnOverscan: number;
  jumpRowOverscan?: number;
  jumpColumnOverscan?: number;
  minimumRenderedRows?: number;
  rowScrollStrategy?: FixedGridRowScrollStrategy;
  scrollRef: React.RefObject<HTMLElement | null>;
  scrollElement?: HTMLElement | null;
  virtualizeColumns?: boolean;
}) {
  const resolvedScrollElement = useResolvedScrollElement({
    scrollRef,
    scrollElement,
  });
  const viewport = useFixedGridViewport(
    resolvedScrollElement,
    rowScrollStrategy,
    {
      rowCount,
      columnCount,
      rowSize,
      columnSize,
    },
  );

  const totalRowSize = fixedTotalSize(rowCount, rowSize);
  const totalColumnSize = fixedTotalSize(columnCount, columnSize);
  const activeRowOverscan = viewport.isJumpingRows
    ? jumpRowOverscan
    : rowOverscan;
  const activeColumnOverscan =
    viewport.isJumpingColumns || viewport.isJumpingRows
      ? jumpColumnOverscan
      : columnOverscan;

  const virtualRows = React.useMemo(
    () =>
      fixedVirtualItems({
        count: rowCount,
        size: rowSize,
        scrollOffset: viewport.scrollTop,
        viewportSize: viewport.clientHeight,
        overscan: activeRowOverscan,
        minimumVisibleCount: minimumRenderedRows,
      }),
    [
      rowCount,
      rowSize,
      viewport.scrollTop,
      viewport.clientHeight,
      activeRowOverscan,
      minimumRenderedRows,
    ],
  );
  const virtualRowWindow = React.useMemo(
    () => fixedVirtualItemWindow(virtualRows),
    [virtualRows],
  );

  const columnWindow = React.useMemo<{
    columnItems: FixedGridColumnItem[];
    leftPad: number;
    rightPad: number;
  }>(() => {
    if (!virtualizeColumns) {
      const safeColumnCount = fixedItemCount(columnCount);
      const safeColumnSize = fixedItemSize(columnSize);
      if (safeColumnCount > MAX_EAGER_COLUMN_ITEMS) {
        return {
          columnItems: [],
          leftPad: 0,
          rightPad: 0,
        };
      }
      return {
        columnItems: Array.from({ length: safeColumnCount }, (_, index) => ({
          index,
          widthPx: safeColumnSize,
        })),
        leftPad: 0,
        rightPad: 0,
      };
    }

    const virtualColumns = fixedVirtualItems({
      count: columnCount,
      size: columnSize,
      scrollOffset: viewport.scrollLeft,
      viewportSize: viewport.clientWidth,
      overscan: activeColumnOverscan,
      minimumVisibleCount: INITIAL_COLUMN_WINDOW,
    });

    return {
      columnItems: virtualColumns.map((item) => ({
        index: item.index,
        widthPx: item.size,
      })),
      leftPad: virtualColumns.length ? virtualColumns[0].start : 0,
      rightPad: virtualColumns.length
        ? totalColumnSize - virtualColumns[virtualColumns.length - 1].end
        : 0,
    };
  }, [
    virtualizeColumns,
    columnCount,
    columnSize,
    viewport.scrollLeft,
    viewport.clientWidth,
    activeColumnOverscan,
    totalColumnSize,
  ]);

  const scrollToCell = React.useCallback(
    ({
      rowIndex,
      columnIndex,
      align = "center",
      behavior = "smooth",
    }: FixedGridScrollTarget) => {
      const scrollElement = scrollRef.current;
      if (!scrollElement) return;
      const top = fixedScrollOffset({
        index: rowIndex,
        itemSize: rowSize,
        viewportSize: scrollElement.clientHeight,
        align,
      });
      const left = fixedScrollOffset({
        index: columnIndex,
        itemSize: columnSize,
        viewportSize: scrollElement.clientWidth,
        align,
      });
      if (typeof scrollElement.scrollTo === "function") {
        scrollElement.scrollTo({ top, left, behavior });
      } else {
        scrollElement.scrollTop = top;
        scrollElement.scrollLeft = left;
      }
    },
    [columnSize, rowSize, scrollRef],
  );

  return {
    virtualRows,
    virtualRowWindow,
    totalRowSize,
    totalColumnSize,
    scrollToCell,
    isJumpingRows: viewport.isJumpingRows,
    isJumpingColumns: viewport.isJumpingColumns,
    viewportClientHeight: viewport.clientHeight,
    ...columnWindow,
  };
}

export function useFixedRowVirtualization({
  rowCount,
  rowSize,
  rowOverscan,
  jumpRowOverscan = rowOverscan,
  initialViewportHeight = 0,
  scrollRef,
  scrollElement,
}: {
  rowCount: number;
  rowSize: number;
  rowOverscan: number;
  jumpRowOverscan?: number;
  initialViewportHeight?: number;
  scrollRef: React.RefObject<HTMLElement | null>;
  scrollElement?: HTMLElement | null;
}) {
  const resolvedScrollElement = useResolvedScrollElement({
    scrollRef,
    scrollElement,
  });
  const [range, setRange] = React.useState(() =>
    initialViewportHeight > 0
      ? fixedRowRange({
          rowCount,
          rowSize,
          scrollTop: 0,
          viewportHeight: initialViewportHeight,
          rowOverscan,
        })
      : { start: 0, end: 0 },
  );
  const rangeRef = React.useRef(range);
  const rafRef = React.useRef(0);
  const totalRowSize = fixedTotalSize(rowCount, rowSize);
  const [viewportClientHeight, setViewportClientHeight] = React.useState(() =>
    fixedViewportMetric(initialViewportHeight),
  );

  const setMeasuredRange = React.useCallback((next: typeof range) => {
    const current = rangeRef.current;
    if (current.start === next.start && current.end === next.end) return;
    rangeRef.current = next;
    setRange(next);
  }, []);
  const setMeasuredViewportHeight = React.useCallback((next: number) => {
    setViewportClientHeight((current) => (current === next ? current : next));
  }, []);

  const measure = React.useCallback(() => {
    const scrollElement = resolvedScrollElement;
    const safeRowCount = fixedItemCount(rowCount);
    const safeRowSize = fixedItemSize(rowSize);
    if (!scrollElement || safeRowCount <= 0 || safeRowSize <= 0) {
      setMeasuredRange({ start: 0, end: 0 });
      return;
    }

    const scrollTop =
      Number.isFinite(scrollElement.scrollTop) && scrollElement.scrollTop > 0
        ? scrollElement.scrollTop
        : 0;
    const viewportHeight =
      Number.isFinite(scrollElement.clientHeight) &&
      scrollElement.clientHeight > 0
        ? scrollElement.clientHeight
        : fixedViewportMetric(initialViewportHeight);
    setMeasuredViewportHeight(viewportHeight);
    const firstVisibleRow = clamp(
      Math.floor(scrollTop / safeRowSize),
      0,
      safeRowCount - 1,
    );
    const visibleRowCount = Math.ceil(viewportHeight / safeRowSize);
    const previous = rangeRef.current;
    const isJumping =
      Math.abs(firstVisibleRow - previous.start) > visibleRowCount * 0.45;
    const activeOverscan = fixedOverscan(
      isJumping ? jumpRowOverscan : rowOverscan,
    );
    const uncappedStart = Math.max(0, firstVisibleRow - activeOverscan);
    const uncappedEnd = Math.min(
      safeRowCount,
      firstVisibleRow + visibleRowCount + activeOverscan,
    );
    const { start, end } = capVirtualRange({
      uncappedStart,
      uncappedEnd,
      visibleStart: firstVisibleRow,
      visibleEnd: Math.min(safeRowCount, firstVisibleRow + visibleRowCount),
      maxItems: MAX_VIRTUAL_ITEMS,
    });

    if (previous.end > safeRowCount || previous.start >= safeRowCount) {
      setMeasuredRange({ start, end });
      return;
    }

    const bufferRows = Math.max(1, Math.floor(activeOverscan / 2));
    const visibleStart = firstVisibleRow;
    const visibleEnd = Math.min(
      safeRowCount,
      firstVisibleRow + visibleRowCount,
    );
    const hasBeforeBuffer =
      previous.start === 0 || visibleStart >= previous.start + bufferRows;
    const hasAfterBuffer =
      previous.end === safeRowCount || visibleEnd <= previous.end - bufferRows;

    if (hasBeforeBuffer && hasAfterBuffer) return;
    setMeasuredRange({ start, end });
  }, [
    jumpRowOverscan,
    initialViewportHeight,
    rowCount,
    rowOverscan,
    rowSize,
    resolvedScrollElement,
    setMeasuredRange,
    setMeasuredViewportHeight,
  ]);

  useKeyedLayoutEffect(joinEffectKey([measure]), () => {
    measure();
  });

  useKeyedMountEffect(joinEffectKey([resolvedScrollElement, measure]), () => {
    const scrollElement = resolvedScrollElement;
    if (!scrollElement) return;

    const scheduleMeasure = () => {
      if (rafRef.current) return;
      let didRun = false;
      const frame = requestAnimationFrame(() => {
        didRun = true;
        rafRef.current = 0;
        measure();
      });
      rafRef.current = didRun ? 0 : frame;
    };

    scrollElement.addEventListener("scroll", scheduleMeasure, {
      passive: true,
    });
    const observer =
      typeof ResizeObserver !== "undefined"
        ? new ResizeObserver(scheduleMeasure)
        : null;
    observer?.observe(scrollElement);
    return () => {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      scrollElement.removeEventListener("scroll", scheduleMeasure);
      observer?.disconnect();
    };
  });

  const virtualRows = React.useMemo(
    () =>
      Array.from({ length: range.end - range.start }, (_, offset) => {
        const index = range.start + offset;
        const size = fixedItemSize(rowSize);
        const start = index * size;
        return {
          index,
          start,
          size,
          end: start + size,
        };
      }),
    [range, rowSize],
  );
  const virtualRowWindow = React.useMemo(
    () => fixedVirtualItemWindow(virtualRows),
    [virtualRows],
  );

  const scrollToRow = React.useCallback(
    ({
      rowIndex,
      align = "center",
      behavior = "smooth",
    }: FixedRowScrollTarget) => {
      const scrollElement = scrollRef.current;
      if (!scrollElement) return;
      const top = fixedScrollOffset({
        index: rowIndex,
        itemSize: rowSize,
        viewportSize: scrollElement.clientHeight,
        align,
      });
      if (typeof scrollElement.scrollTo === "function") {
        scrollElement.scrollTo({ top, behavior });
      } else {
        scrollElement.scrollTop = top;
      }
    },
    [rowSize, scrollRef],
  );

  return {
    virtualRows,
    virtualRowWindow,
    totalRowSize,
    viewportClientHeight,
    scrollToRow,
  };
}

function fixedRowRange({
  rowCount,
  rowSize,
  scrollTop,
  viewportHeight,
  rowOverscan,
}: {
  rowCount: number;
  rowSize: number;
  scrollTop: number;
  viewportHeight: number;
  rowOverscan: number;
}) {
  const safeRowCount = fixedItemCount(rowCount);
  const safeRowSize = fixedItemSize(rowSize);
  if (safeRowCount <= 0 || safeRowSize <= 0) return { start: 0, end: 0 };

  const safeScrollTop =
    Number.isFinite(scrollTop) && scrollTop > 0 ? scrollTop : 0;
  const safeViewportHeight = fixedViewportMetric(viewportHeight);
  const firstVisibleRow = clamp(
    Math.floor(safeScrollTop / safeRowSize),
    0,
    safeRowCount - 1,
  );
  const visibleRowCount = Math.ceil(safeViewportHeight / safeRowSize);
  const activeOverscan = fixedOverscan(rowOverscan);
  const uncappedStart = Math.max(0, firstVisibleRow - activeOverscan);
  const uncappedEnd = Math.min(
    safeRowCount,
    firstVisibleRow + visibleRowCount + activeOverscan,
  );
  return capVirtualRange({
    uncappedStart,
    uncappedEnd,
    visibleStart: firstVisibleRow,
    visibleEnd: Math.min(safeRowCount, firstVisibleRow + visibleRowCount),
    maxItems: MAX_VIRTUAL_ITEMS,
  });
}

export interface FixedGridViewport {
  scrollTop: number;
  scrollLeft: number;
  clientHeight: number;
  clientWidth: number;
  isJumpingRows: boolean;
  isJumpingColumns: boolean;
}

interface FixedGridLayoutMetrics {
  rowCount: number;
  columnCount: number;
  rowSize: number;
  columnSize: number;
}

interface FixedGridReadingAnchor {
  rowIndex: number;
  columnIndex: number;
  rowOffsetPx: number;
  columnOffsetPx: number;
}

interface FixedVirtualWindow {
  count: number;
  size: number;
  scrollOffset: number;
  viewportSize: number;
  overscan: number;
  minimumVisibleCount?: number;
}

const emptyFixedGridViewport: FixedGridViewport = {
  scrollTop: 0,
  scrollLeft: 0,
  clientHeight: 0,
  clientWidth: 0,
  isJumpingRows: false,
  isJumpingColumns: false,
};

function useResolvedScrollElement({
  scrollRef,
  scrollElement,
}: {
  scrollRef: React.RefObject<HTMLElement | null>;
  scrollElement?: HTMLElement | null;
}) {
  const [resolvedScrollElement, setResolvedScrollElement] =
    React.useState<HTMLElement | null>(scrollElement ?? scrollRef.current);

  useKeyedLayoutEffect(
    joinEffectKey([
      scrollRef,
      scrollRef.current,
      scrollElement,
      resolvedScrollElement,
    ]),
    () => {
      const nextScrollElement = scrollElement ?? scrollRef.current;
      if (resolvedScrollElement !== nextScrollElement) {
        setResolvedScrollElement(nextScrollElement);
      }
    },
  );

  return resolvedScrollElement;
}

function useFixedGridViewport(
  scrollElement: HTMLElement | null | undefined,
  rowScrollStrategy?: FixedGridRowScrollStrategy,
  layoutMetrics?: FixedGridLayoutMetrics,
) {
  const [viewport, setViewport] = React.useState<FixedGridViewport>(
    emptyFixedGridViewport,
  );
  const committedLayoutMetricsRef = React.useRef<FixedGridLayoutMetrics | null>(
    layoutMetrics ?? null,
  );

  useKeyedLayoutEffect(
    joinEffectKey([
      scrollElement,
      rowScrollStrategy,
      layoutMetrics?.rowCount,
      layoutMetrics?.columnCount,
      layoutMetrics?.rowSize,
      layoutMetrics?.columnSize,
    ]),
    () => {
      const previousLayoutMetrics = committedLayoutMetricsRef.current;
      committedLayoutMetricsRef.current = layoutMetrics ?? null;

      if (!scrollElement) {
        setViewport((current) =>
          fixedGridViewportEqual(current, emptyFixedGridViewport)
            ? current
            : emptyFixedGridViewport,
        );
        return;
      }

      let frame = 0;
      let settleTimeout = 0;
      let lastScrollTop = scrollElement.scrollTop;
      let lastScrollLeft = scrollElement.scrollLeft;

      if (
        previousLayoutMetrics &&
        layoutMetrics &&
        didFixedGridItemSizeChange(previousLayoutMetrics, layoutMetrics)
      ) {
        const anchor = captureFixedGridReadingAnchor({
          layoutMetrics: previousLayoutMetrics,
          scrollElement,
        });
        restoreFixedGridReadingAnchor({
          anchor,
          layoutMetrics,
          scrollElement,
        });
        lastScrollTop = scrollElement.scrollTop;
        lastScrollLeft = scrollElement.scrollLeft;
      }

      const commitViewport = (next: FixedGridViewport) => {
        setViewport((current) => {
          return fixedGridViewportEqual(current, next) ? current : next;
        });
      };

      const commitSettledViewport = () => {
        commitViewport({
          scrollTop: fixedViewportMetric(scrollElement.scrollTop),
          scrollLeft: fixedViewportMetric(scrollElement.scrollLeft),
          clientHeight: fixedViewportMetric(scrollElement.clientHeight),
          clientWidth: fixedViewportMetric(scrollElement.clientWidth),
          isJumpingRows: false,
          isJumpingColumns: false,
        });
      };

      const scheduleSettledViewport = () => {
        if (settleTimeout) window.clearTimeout(settleTimeout);
        settleTimeout = window.setTimeout(() => {
          settleTimeout = 0;
          // Scrolling has quiesced: re-read the live scroll metrics so the
          // canonical React window matches where the grid actually came to rest,
          // then clear jump flags so settled windows use the full overscan.
          commitSettledViewport();
        }, rowScrollStrategy?.settleAfterMs ?? 80);
      };

      const readViewport = () => {
        frame = 0;
        const scrollTop = fixedViewportMetric(scrollElement.scrollTop);
        const scrollLeft = fixedViewportMetric(scrollElement.scrollLeft);
        const clientHeight = fixedViewportMetric(scrollElement.clientHeight);
        const clientWidth = fixedViewportMetric(scrollElement.clientWidth);
        const rowDelta = Math.abs(scrollTop - lastScrollTop);
        const columnDelta = Math.abs(scrollLeft - lastScrollLeft);
        lastScrollTop = scrollTop;
        lastScrollLeft = scrollLeft;

        const next: FixedGridViewport = {
          scrollTop,
          scrollLeft,
          clientHeight,
          clientWidth,
          isJumpingRows: rowDelta > clientHeight * 0.45,
          isJumpingColumns: columnDelta > clientWidth * 0.45,
        };

        if (
          rowDelta > 0 &&
          rowScrollStrategy?.handleViewport(next) === "handled"
        ) {
          scheduleSettledViewport();
          return;
        }

        commitViewport(next);
        if (next.isJumpingRows || next.isJumpingColumns) {
          scheduleSettledViewport();
          return;
        }
        if (settleTimeout) {
          window.clearTimeout(settleTimeout);
          settleTimeout = 0;
        }
      };

      const scheduleRead = () => {
        if (frame) return;
        let didRun = false;
        const nextFrame = requestAnimationFrame(() => {
          didRun = true;
          readViewport();
        });
        frame = didRun ? 0 : nextFrame;
      };

      readViewport();
      scrollElement.addEventListener("scroll", scheduleRead, { passive: true });
      const observer =
        typeof ResizeObserver !== "undefined"
          ? new ResizeObserver(scheduleRead)
          : null;
      observer?.observe(scrollElement);

      return () => {
        if (frame) cancelAnimationFrame(frame);
        if (settleTimeout) window.clearTimeout(settleTimeout);
        scrollElement.removeEventListener("scroll", scheduleRead);
        observer?.disconnect();
      };
    },
  );

  return viewport;
}

function didFixedGridItemSizeChange(
  previous: FixedGridLayoutMetrics,
  next: FixedGridLayoutMetrics,
) {
  return (
    previous.rowSize !== next.rowSize || previous.columnSize !== next.columnSize
  );
}

function captureFixedGridReadingAnchor({
  layoutMetrics,
  scrollElement,
}: {
  layoutMetrics: FixedGridLayoutMetrics;
  scrollElement: HTMLElement;
}): FixedGridReadingAnchor {
  const rowCount = fixedItemCount(layoutMetrics.rowCount);
  const columnCount = fixedItemCount(layoutMetrics.columnCount);
  const rowSize = fixedItemSize(layoutMetrics.rowSize);
  const columnSize = fixedItemSize(layoutMetrics.columnSize);
  const scrollTop = fixedViewportMetric(scrollElement.scrollTop);
  const scrollLeft = fixedViewportMetric(scrollElement.scrollLeft);
  const rowIndex =
    rowCount > 0 && rowSize > 0
      ? clamp(Math.floor(scrollTop / rowSize), 0, rowCount - 1)
      : 0;
  const columnIndex =
    columnCount > 0 && columnSize > 0
      ? clamp(Math.floor(scrollLeft / columnSize), 0, columnCount - 1)
      : 0;

  return {
    rowIndex,
    columnIndex,
    rowOffsetPx: Math.max(0, scrollTop - rowIndex * rowSize),
    columnOffsetPx: Math.max(0, scrollLeft - columnIndex * columnSize),
  };
}

function restoreFixedGridReadingAnchor({
  anchor,
  layoutMetrics,
  scrollElement,
}: {
  anchor: FixedGridReadingAnchor;
  layoutMetrics: FixedGridLayoutMetrics;
  scrollElement: HTMLElement;
}) {
  const rowCount = fixedItemCount(layoutMetrics.rowCount);
  const columnCount = fixedItemCount(layoutMetrics.columnCount);
  const rowSize = fixedItemSize(layoutMetrics.rowSize);
  const columnSize = fixedItemSize(layoutMetrics.columnSize);
  const rowIndex = rowCount > 0 ? clamp(anchor.rowIndex, 0, rowCount - 1) : 0;
  const columnIndex =
    columnCount > 0 ? clamp(anchor.columnIndex, 0, columnCount - 1) : 0;

  scrollElement.scrollTop =
    rowIndex * rowSize + Math.min(anchor.rowOffsetPx, Math.max(0, rowSize - 1));
  scrollElement.scrollLeft =
    columnIndex * columnSize +
    Math.min(anchor.columnOffsetPx, Math.max(0, columnSize - 1));
}

export function fixedVirtualItems({
  count,
  size,
  scrollOffset,
  viewportSize,
  overscan,
  minimumVisibleCount = 1,
}: FixedVirtualWindow): FixedGridVirtualItem[] {
  if (!Number.isFinite(count) || !Number.isFinite(size)) return [];
  const itemCount = Math.floor(count);
  if (itemCount <= 0 || size <= 0) return [];
  const safeScrollOffset =
    Number.isFinite(scrollOffset) && scrollOffset > 0 ? scrollOffset : 0;
  const safeViewportSize = Number.isFinite(viewportSize) ? viewportSize : 0;
  const safeOverscan =
    Number.isFinite(overscan) && overscan > 0 ? Math.floor(overscan) : 0;
  const safeMinimumVisibleCount =
    Number.isFinite(minimumVisibleCount) && minimumVisibleCount > 0
      ? Math.ceil(minimumVisibleCount)
      : 1;
  const effectiveViewportSize = Math.max(
    safeViewportSize,
    size * safeMinimumVisibleCount,
  );
  const visibleStart = clamp(
    Math.floor(safeScrollOffset / size),
    0,
    itemCount - 1,
  );
  const visibleEnd = clamp(
    Math.ceil((safeScrollOffset + effectiveViewportSize) / size),
    visibleStart,
    itemCount - 1,
  );
  const uncappedStart = Math.max(0, visibleStart - safeOverscan);
  const uncappedEndInclusive = Math.min(
    itemCount - 1,
    visibleEnd + safeOverscan,
  );
  const { start, end } = capVirtualRange({
    uncappedStart,
    uncappedEnd: uncappedEndInclusive + 1,
    visibleStart,
    visibleEnd: visibleEnd + 1,
    maxItems: MAX_VIRTUAL_ITEMS,
  });
  return Array.from({ length: end - start }, (_, offset) => {
    const index = start + offset;
    const itemStart = index * size;
    return {
      index,
      start: itemStart,
      size,
      end: itemStart + size,
    };
  });
}

export function fixedVirtualItemWindow(
  items: readonly FixedGridVirtualItem[],
): FixedGridVirtualItemWindow {
  const start = items[0]?.start ?? 0;
  const end = items.length ? items[items.length - 1]!.end : start;

  return {
    end,
    items: items.map((item) => ({
      ...item,
      start: item.start - start,
      end: item.end - start,
    })),
    size: Math.max(0, end - start),
    start,
  };
}

function capVirtualRange({
  uncappedStart,
  uncappedEnd,
  visibleStart,
  visibleEnd,
  maxItems,
}: {
  uncappedStart: number;
  uncappedEnd: number;
  visibleStart: number;
  visibleEnd: number;
  maxItems: number;
}) {
  const length = uncappedEnd - uncappedStart;
  if (length <= maxItems) return { start: uncappedStart, end: uncappedEnd };

  const visibleLength = Math.max(0, visibleEnd - visibleStart);
  if (visibleLength >= maxItems) {
    return {
      start: visibleStart,
      end: visibleStart + maxItems,
    };
  }

  const remaining = maxItems - visibleLength;
  const before = Math.min(
    visibleStart - uncappedStart,
    Math.floor(remaining / 2),
  );
  let start = visibleStart - before;
  let end = start + maxItems;

  if (end > uncappedEnd) {
    end = uncappedEnd;
    start = Math.max(uncappedStart, end - maxItems);
  }

  return { start, end };
}

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}

function fixedTotalSize(count: number, size: number) {
  if (
    !Number.isFinite(count) ||
    !Number.isFinite(size) ||
    count <= 0 ||
    size <= 0
  ) {
    return 0;
  }
  const totalSize = Math.floor(count) * size;
  return Number.isFinite(totalSize) ? totalSize : 0;
}

function fixedItemCount(count: number) {
  return Number.isFinite(count) && count > 0 ? Math.floor(count) : 0;
}

function fixedItemSize(size: number) {
  return Number.isFinite(size) && size > 0 ? size : 0;
}

function fixedOverscan(overscan: number) {
  return Number.isFinite(overscan) && overscan > 0 ? Math.floor(overscan) : 0;
}

function fixedViewportMetric(value: number) {
  return Number.isFinite(value) && value > 0 ? value : 0;
}

export function fixedScrollOffset({
  index,
  itemSize,
  viewportSize,
  align,
}: {
  index: number;
  itemSize: number;
  viewportSize: number;
  align: NonNullable<FixedGridScrollTarget["align"]>;
}) {
  if (
    !Number.isSafeInteger(index) ||
    !Number.isFinite(itemSize) ||
    !Number.isFinite(viewportSize) ||
    index < 0 ||
    itemSize <= 0 ||
    viewportSize < 0
  ) {
    return 0;
  }
  const start = index * itemSize;
  if (align === "end") return Math.max(0, start - viewportSize + itemSize);
  if (align === "center") {
    return Math.max(0, start - viewportSize / 2 + itemSize / 2);
  }
  return Math.max(0, start);
}

function fixedGridViewportEqual(
  left: FixedGridViewport,
  right: FixedGridViewport,
) {
  return (
    left.scrollTop === right.scrollTop &&
    left.scrollLeft === right.scrollLeft &&
    left.clientHeight === right.clientHeight &&
    left.clientWidth === right.clientWidth &&
    left.isJumpingRows === right.isJumpingRows &&
    left.isJumpingColumns === right.isJumpingColumns
  );
}

import type * as React from "react";

export function getFixedGridRowStyle({
  gridTemplate,
  rowHeight,
  top,
  contain = true,
}: {
  gridTemplate?: string;
  rowHeight: number;
  top: number;
  contain?: boolean;
}): React.CSSProperties {
  const safeRowHeight =
    Number.isFinite(rowHeight) && rowHeight > 0 ? rowHeight : 0;
  const safeTop = Number.isFinite(top) && top > 0 ? top : 0;
  const style: React.CSSProperties = {
    height: safeRowHeight,
    minHeight: safeRowHeight,
    position: "absolute",
    top: 0,
    left: 0,
    width: "100%",
    transform: `translate3d(0, ${safeTop}px, 0)`,
  };
  if (gridTemplate?.trim()) style.gridTemplateColumns = gridTemplate;
  if (contain) style.contain = "layout paint style";
  return style;
}

export function buildVirtualGridTemplate({
  leadingWidth,
  leftPad,
  columnWidths,
  rightPad,
}: {
  leadingWidth: number;
  leftPad: number;
  columnWidths: readonly number[];
  rightPad: number;
}) {
  const columns = columnWidths.map(formatTemplateWidth).join(" ");
  return [
    formatTemplateWidth(leadingWidth),
    formatTemplateWidth(leftPad),
    columns,
    formatTemplateWidth(rightPad),
  ]
    .filter(Boolean)
    .join(" ");
}

function formatTemplateWidth(width: number) {
  return `${Number.isFinite(width) && width > 0 ? width : 0}px`;
}

export interface FixedGridColumn<Metadata = unknown> {
  key: string;
  widthPx: number;
  metadata?: Metadata;
}

export function buildFixedGridColumns<Item, Metadata = unknown>({
  items,
  getKey,
  getWidthPx,
  getMetadata,
}: {
  items: readonly Item[];
  getKey: (item: Item, index: number) => string;
  getWidthPx: (item: Item, index: number) => number;
  getMetadata?: (item: Item, index: number) => Metadata | undefined;
}): FixedGridColumn<Metadata>[] {
  return items.map((item, index) => {
    const metadata = getMetadata?.(item, index);
    const widthPx = normalizeFixedGridColumnWidth(getWidthPx(item, index));
    return metadata === undefined
      ? {
          key: getKey(item, index),
          widthPx,
        }
      : {
          key: getKey(item, index),
          widthPx,
          metadata,
        };
  });
}

export function fixedGridColumnWidths(
  columns: readonly Pick<FixedGridColumn, "widthPx">[],
) {
  return columns.map((column) => normalizeFixedGridColumnWidth(column.widthPx));
}

function normalizeFixedGridColumnWidth(widthPx: number) {
  return Number.isFinite(widthPx) && widthPx > 0 ? widthPx : 0;
}

import type * as React from "react";

export type CssLength = number | string;
type CssLengthProperty = "height" | "marginTop" | "minWidth" | "width";

export interface FixedGridInverseRowWindowGeometry {
  size: number;
  start: number;
}

export function getFixedGridCanvasStyle({
  width,
  minWidth = "100%",
  contain = false,
}: {
  width?: CssLength;
  minWidth?: CssLength;
  contain?: boolean;
}): React.CSSProperties {
  return {
    position: "relative",
    ...cssLengthProperty("width", width),
    ...cssLengthProperty("minWidth", minWidth),
    ...(contain ? { contain: "layout paint style" } : null),
  };
}

export function getFixedGridRowWindowStyle({
  height,
  minWidth,
}: {
  height: CssLength;
  minWidth?: CssLength;
}): React.CSSProperties {
  return {
    position: "relative",
    ...cssLengthProperty("height", height),
    ...cssLengthProperty("minWidth", minWidth),
  };
}

export function getFixedGridInverseRowOffsetStyle({
  height,
  minWidth,
}: {
  height: CssLength;
  minWidth?: CssLength;
}): React.CSSProperties {
  return {
    ...cssLengthProperty("height", height),
    ...cssLengthProperty("minWidth", minWidth),
  };
}

export function getFixedGridInverseStickyRowWindowStyle({
  height,
  minWidth,
  viewportHeight,
}: {
  height: number;
  minWidth?: CssLength;
  viewportHeight: number;
}): React.CSSProperties {
  const stickyOffset = fixedGridInverseStickyOffset({
    viewportSize: viewportHeight,
    windowSize: height,
  });

  return {
    position: "sticky",
    ...cssLengthProperty("height", height),
    ...cssLengthProperty("minWidth", minWidth),
    top: `${stickyOffset}px`,
    bottom: `${stickyOffset}px`,
  };
}

export function getFixedGridInverseRowWindowStyles({
  minWidth,
  rowMinWidth,
  totalSize,
  viewportHeight,
  window,
}: {
  minWidth?: CssLength;
  rowMinWidth?: CssLength;
  totalSize: CssLength;
  viewportHeight: number;
  window: FixedGridInverseRowWindowGeometry;
}): {
  offsetStyle: React.CSSProperties;
  spacerStyle: React.CSSProperties;
  windowStyle: React.CSSProperties;
} {
  return {
    offsetStyle: getFixedGridInverseRowOffsetStyle({
      height: window.start,
      minWidth: rowMinWidth,
    }),
    spacerStyle: getFixedGridRowWindowStyle({
      height: totalSize,
      minWidth,
    }),
    windowStyle: getFixedGridInverseStickyRowWindowStyle({
      height: window.size,
      minWidth: rowMinWidth,
      viewportHeight,
    }),
  };
}

export function getFixedGridInverseRowWindowStyle({
  height,
  minWidth,
  top,
  viewportHeight,
}: {
  height: number;
  minWidth?: CssLength;
  top: number;
  viewportHeight: number;
}): React.CSSProperties {
  const stickyOffset = fixedGridInverseStickyOffset({
    viewportSize: viewportHeight,
    windowSize: height,
  });

  return {
    position: "sticky",
    ...cssLengthProperty("height", height),
    ...cssLengthProperty("marginTop", top),
    ...cssLengthProperty("minWidth", minWidth),
    top: `${stickyOffset}px`,
    bottom: `${stickyOffset}px`,
  };
}

export function fixedGridInverseStickyOffset({
  viewportSize,
  windowSize,
}: {
  viewportSize: number;
  windowSize: number;
}) {
  const offset = Math.max(
    0,
    safeCssNumber(windowSize) - safeCssNumber(viewportSize),
  );
  return offset === 0 ? 0 : -offset;
}

export function setFixedGridInverseRowWindowGeometry({
  rowOffsetElement,
  rowWindowElement,
  viewportHeight,
  window,
}: {
  rowOffsetElement: HTMLElement;
  rowWindowElement: HTMLElement;
  viewportHeight: number;
  window: FixedGridInverseRowWindowGeometry;
}) {
  const offsetStyle = getFixedGridInverseRowOffsetStyle({
    height: window.start,
  });
  const windowStyle = getFixedGridInverseStickyRowWindowStyle({
    height: window.size,
    viewportHeight,
  });
  patchStyleProperties(rowOffsetElement.style, offsetStyle, ["height"]);
  patchStyleProperties(rowWindowElement.style, windowStyle, [
    "position",
    "height",
    "top",
    "bottom",
  ]);
  setStyleValue(rowWindowElement.style, "margin-top", "");
}

function formatCssLength(value: CssLength | undefined) {
  if (typeof value === "string") return value.trim() ? value : undefined;
  if (typeof value !== "number") return value;
  return Number.isFinite(value) && value >= 0 ? `${value}px` : undefined;
}

function cssLengthProperty<Property extends CssLengthProperty>(
  property: Property,
  value: CssLength | undefined,
): Pick<React.CSSProperties, Property> | object {
  const formattedValue = formatCssLength(value);
  return formattedValue === undefined ? {} : { [property]: formattedValue };
}

function safeCssNumber(value: number) {
  return Number.isFinite(value) && value > 0 ? value : 0;
}

function patchStyleProperties(
  style: CSSStyleDeclaration,
  values: React.CSSProperties,
  properties: string[],
) {
  for (const property of properties) {
    const value = values[property as keyof React.CSSProperties];
    setStyleValue(
      style,
      property,
      typeof value === "number" ? `${value}px` : value,
    );
  }
}

function setStyleValue(
  style: CSSStyleDeclaration,
  propertyName: string,
  value: unknown,
) {
  const nextValue = typeof value === "string" ? value : "";
  if (style.getPropertyValue(propertyName) !== nextValue) {
    style.setProperty(propertyName, nextValue);
  }
}

export interface GridCellCoordinate {
  rowIndex: number;
  columnIndex: number;
}

export function isSameGridCell(
  left: GridCellCoordinate | null | undefined,
  right: GridCellCoordinate | null | undefined,
) {
  return (
    isValidGridCellCoordinate(left) &&
    isValidGridCellCoordinate(right) &&
    left.rowIndex === right.rowIndex &&
    left.columnIndex === right.columnIndex
  );
}

export function gridCellKey({ rowIndex, columnIndex }: GridCellCoordinate) {
  if (!isValidGridCellCoordinate({ rowIndex, columnIndex })) return null;
  return `${rowIndex}:${columnIndex}`;
}

export function parseGridCellKey(key: string): GridCellCoordinate | null {
  const [rowIndexText, columnIndexText, extra] = key.split(":");
  if (extra !== undefined) return null;
  if (!rowIndexText || !columnIndexText) return null;
  if (
    !isUnsignedIntegerText(rowIndexText) ||
    !isUnsignedIntegerText(columnIndexText)
  ) {
    return null;
  }

  const rowIndex = Number(rowIndexText);
  const columnIndex = Number(columnIndexText);
  if (!isValidGridCellCoordinate({ rowIndex, columnIndex })) {
    return null;
  }

  return { rowIndex, columnIndex };
}

function isUnsignedIntegerText(value: string) {
  return /^(0|[1-9]\d*)$/.test(value);
}

function isValidGridCellCoordinate(
  coordinate: GridCellCoordinate | null | undefined,
): coordinate is GridCellCoordinate {
  return (
    !!coordinate &&
    Number.isSafeInteger(coordinate.rowIndex) &&
    Number.isSafeInteger(coordinate.columnIndex) &&
    coordinate.rowIndex >= 0 &&
    coordinate.columnIndex >= 0
  );
}

"use client";

import * as React from "react";

export interface FixedGridViewportRefs {
  scrollElement: HTMLDivElement | null;
}

export interface FixedGridViewportProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "children"> {
  scrollRef: React.Ref<HTMLDivElement>;
  dataSlot: string;
  children: React.ReactNode;
}

export function FixedGridViewport({
  scrollRef,
  dataSlot,
  className = "absolute inset-0 overflow-auto",
  children,
  ...props
}: FixedGridViewportProps) {
  return (
    <div ref={scrollRef} data-slot={dataSlot} className={className} {...props}>
      {children}
    </div>
  );
}

"use client";

import * as React from "react";
import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { useKeyedLayoutEffect } from "@/hooks/use-keyed-layout-effect";
import { joinEffectKey } from "@/lib/effect-key";

export function HeaderAwareScrollbar({
  scrollRef,
  headerHeight,
}: {
  scrollRef: React.RefObject<HTMLDivElement | null>;
  headerHeight: number;
}) {
  const scrollElement = useResolvedScrollbarElement(scrollRef);
  const [isVisible, setIsVisible] = React.useState(false);
  const thumbRef = React.useRef<HTMLDivElement>(null);
  const thumbMetrics = React.useRef({ height: 0, top: 0 });
  const drag = React.useRef<{ y: number; scroll: number } | null>(null);
  const frame = React.useRef(0);

  const measure = React.useCallback(() => {
    frame.current = 0;
    if (!scrollElement) {
      hideThumb(setIsVisible);
      return;
    }
    const { scrollHeight, clientHeight, scrollTop } = scrollElement;
    if (
      !Number.isFinite(scrollHeight) ||
      !Number.isFinite(clientHeight) ||
      !Number.isFinite(scrollTop) ||
      !Number.isFinite(headerHeight)
    ) {
      hideThumb(setIsVisible);
      return;
    }
    const track = clientHeight - headerHeight;
    if (scrollHeight <= clientHeight + 1 || track <= 0) {
      hideThumb(setIsVisible);
      return;
    }
    const height = Math.max(28, (clientHeight / scrollHeight) * track);
    const maxScroll = scrollHeight - clientHeight;
    const maxTop = track - height;
    const top =
      maxScroll > 0
        ? clampScrollTop((scrollTop / maxScroll) * maxTop, maxTop)
        : 0;
    thumbMetrics.current = { height, top };
    applyThumbStyle(thumbRef.current, thumbMetrics.current);
    setIsVisible((current) => (current ? current : true));
  }, [scrollElement, headerHeight]);

  const scheduleMeasure = React.useCallback(() => {
    if (frame.current) return;
    frame.current = requestAnimationFrame(measure);
  }, [measure]);

  useKeyedMountEffect(
    joinEffectKey([scrollElement, measure, scheduleMeasure]),
    () => {
      if (!scrollElement) {
        hideThumb(setIsVisible);
        return;
      }
      measure();
      scrollElement.addEventListener("scroll", scheduleMeasure, {
        passive: true,
      });
      const observer =
        typeof ResizeObserver !== "undefined"
          ? new ResizeObserver(scheduleMeasure)
          : null;
      observer?.observe(scrollElement);
      return () => {
        if (frame.current) cancelAnimationFrame(frame.current);
        scrollElement.removeEventListener("scroll", scheduleMeasure);
        observer?.disconnect();
      };
    },
  );

  useKeyedLayoutEffect(joinEffectKey([isVisible]), () => {
    applyThumbStyle(thumbRef.current, thumbMetrics.current);
  });

  const onPointerDown = (event: React.PointerEvent<HTMLDivElement>) => {
    if (!scrollElement) return;
    event.preventDefault();
    drag.current = { y: event.clientY, scroll: scrollElement.scrollTop };
    event.currentTarget.setPointerCapture?.(event.pointerId);
  };

  const onPointerMove = (event: React.PointerEvent<HTMLDivElement>) => {
    const currentDrag = drag.current;
    if (!scrollElement || !currentDrag) return;
    const track = scrollElement.clientHeight - headerHeight;
    const height = Math.max(
      28,
      (scrollElement.clientHeight / scrollElement.scrollHeight) * track,
    );
    const denominator = track - height;
    if (denominator <= 0) return;
    const maxScroll = scrollElement.scrollHeight - scrollElement.clientHeight;
    scrollElement.scrollTop = clampScrollTop(
      currentDrag.scroll +
        ((event.clientY - currentDrag.y) / denominator) * maxScroll,
      maxScroll,
    );
  };

  const endDrag = (event: React.PointerEvent<HTMLDivElement>) => {
    drag.current = null;
    event.currentTarget.releasePointerCapture?.(event.pointerId);
  };

  if (!isVisible) return null;
  return (
    <div
      aria-hidden
      className="pointer-events-none absolute right-0 z-30 w-2.5"
      style={{ top: headerHeight, bottom: 0 }}
    >
      <div
        ref={thumbRef}
        className="bg-foreground/25 hover:bg-foreground/40 pointer-events-auto absolute right-0.5 w-1.5 rounded-full transition-colors"
        style={{
          top: 0,
          height: thumbMetrics.current.height,
          transform: `translateY(${thumbMetrics.current.top}px)`,
        }}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={endDrag}
        onPointerCancel={endDrag}
      />
    </div>
  );
}

function useResolvedScrollbarElement(
  scrollRef: React.RefObject<HTMLDivElement | null>,
) {
  const [scrollElement, setScrollElement] = React.useState(scrollRef.current);

  useKeyedLayoutEffect(
    joinEffectKey([scrollRef, scrollRef.current, scrollElement]),
    () => {
      const nextScrollElement = scrollRef.current;
      if (scrollElement !== nextScrollElement) {
        setScrollElement(nextScrollElement);
      }
    },
  );

  return scrollElement;
}

function hideThumb(setThumb: React.Dispatch<React.SetStateAction<boolean>>) {
  setThumb((current) => (current ? false : current));
}

function clampScrollTop(value: number, maxScroll: number) {
  if (!Number.isFinite(value)) return 0;
  if (!Number.isFinite(maxScroll) || maxScroll <= 0) return 0;
  return Math.min(maxScroll, Math.max(0, value));
}

function applyThumbStyle(
  element: HTMLDivElement | null,
  metrics: { height: number; top: number },
) {
  if (!element) return;
  element.style.height = `${metrics.height}px`;
  element.style.transform = `translateY(${metrics.top}px)`;
}

export function viewerScrollbarCss(slotName: string) {
  return `
[data-slot="${slotName}"]::-webkit-scrollbar { width: 10px; height: 10px; }
[data-slot="${slotName}"]::-webkit-scrollbar:vertical { display: none; }
[data-slot="${slotName}"]::-webkit-scrollbar-track { background: transparent; }
[data-slot="${slotName}"]::-webkit-scrollbar-thumb {
  background-color: color-mix(in oklab, var(--foreground) 22%, transparent);
  border-radius: 9999px;
  border: 3px solid transparent;
  background-clip: content-box;
}
[data-slot="${slotName}"]::-webkit-scrollbar-thumb:hover {
  background-color: color-mix(in oklab, var(--foreground) 38%, transparent);
}
`;
}

