import { resolveCsvDialect, type CsvDialect, type CsvTable } from "@/lib/csv";
import type {
  ViewerContentPayload,
  ViewerContentBlob,
  ViewerContentStream,
  ViewerResource,
} from "@/lib/viewer-resource";
import { viewerContentRenderKey } from "@/lib/viewer-resource";
import type {
  BlobViewerSource,
  TextSource,
  UrlViewerSource,
} from "@/lib/viewer-source";
import { textPayloadKey } from "@/lib/viewer-source";

export type CsvContent = ViewerContentPayload &
  ViewerContentBlob &
  ViewerContentStream;

export type CsvResource =
  | { kind: "resource"; content: CsvContent }
  | { kind: "text"; text: string }
  | { kind: "table"; table: CsvTable; fileName?: string }
  | { kind: "empty" };

export type CsvDocumentSource = UrlViewerSource | BlobViewerSource | TextSource;

export interface CsvTableSource {
  kind: "table";
  table: CsvTable;
  fileName?: string;
  identityKey?: string;
  dialect?: CsvDialect;
}

export type CsvViewerSource = CsvDocumentSource | CsvTableSource;

export interface CsvResourceInput {
  source?: CsvViewerSource;
  resource?: ViewerResource | null;
}

export interface CsvViewerDialectInput {
  dialect?: CsvDialect;
  source?: CsvViewerSource;
  resource?: ViewerResource | null;
}

export function isCsvDocumentSource(
  source: CsvViewerSource,
): source is CsvDocumentSource {
  return source.kind !== "table";
}

export function resolveCsvResource({
  source,
  resource,
}: CsvResourceInput): CsvResource {
  if (source?.kind === "table") {
    return {
      kind: "table",
      table: source.table,
      fileName: source.fileName,
    };
  }
  if (resource) {
    if (resource.content.payload.kind === "text") {
      return { kind: "text", text: resource.content.payload.text };
    }
    return { kind: "resource", content: resource.content };
  }
  return { kind: "empty" };
}

export function resolveCsvViewerDialect({
  dialect,
  source,
  resource,
}: CsvViewerDialectInput): CsvDialect {
  const tableDialect = source?.kind === "table" ? source.dialect : undefined;
  const tableFileName = source?.kind === "table" ? source.fileName : undefined;
  return resolveCsvDialect({
    dialect: dialect ?? tableDialect,
    descriptor: {
      src: resource?.content.directUrl ?? undefined,
      fileName: resource?.fileName ?? tableFileName,
      mimeType: resource?.mimeType,
    },
  });
}

export function csvViewerSortResetKey({
  dialect,
  source,
  resource,
}: {
  dialect: CsvDialect;
  source?: CsvViewerSource;
  resource?: ViewerResource | null;
}): unknown {
  const dialectKey = `${dialect.delimiter}\u0000${dialect.hasHeader}`;
  if (source?.kind === "text") {
    return `${source.identityKey ?? ""}\u0000${textPayloadKey(source.text)}\u0000${dialectKey}`;
  }
  if (resource) {
    return `${resource.keys.load}\u0000${viewerContentRenderKey(resource.content)}\u0000${dialectKey}`;
  }
  if (source?.kind === "table") return source.identityKey ?? source.table;
  return "empty";
}

export function csvViewerExportFileName({
  dialect,
  source,
  resource,
  fallback,
}: {
  dialect: CsvDialect;
  source?: CsvViewerSource;
  resource?: ViewerResource | null;
  fallback: (dialect: CsvDialect) => string;
}): string {
  const tableFileName = source?.kind === "table" ? source.fileName : undefined;
  return resource?.fileName ?? tableFileName ?? fallback(dialect);
}

import * as React from "react";

import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import {
  parseCsv,
  streamCsv,
  type CsvDialect,
  type CsvStreamSource,
} from "@/lib/csv";
import {
  isAbortError,
  isResourceError,
  ResourceError,
} from "@/lib/viewer-errors";

import {
  resolveCsvResource,
  type CsvResource,
  type CsvResourceInput,
} from "./csv-viewer-resource";
import {
  createCsvRowStoreFromRows,
  createMutableCsvRowStore,
  emptyCsvRowStore,
  type CsvRowStore,
} from "./csv-row-store";
import {
  CsvWorkerUnavailableError,
  parseCsvInWorker,
  toCsvFormatError,
} from "./csv-viewer-worker";
import type { GridCellCoordinate } from "./fixed-grid-selection";
import { joinEffectKey } from "@/lib/effect-key";

const CSV_STREAM_BATCH_SIZE = 5000;
const SYNC_TEXT_PARSE_MAX_BYTES = 256 * 1024;

export type CsvCellAddress = GridCellCoordinate;

export type CsvResourceState =
  | {
      status: "idle";
      columns: string[];
      sourceRows: string[][];
      rowStore: CsvRowStore;
    }
  | {
      status: "loading";
      columns: string[];
      sourceRows: string[][];
      rowStore: CsvRowStore;
    }
  | {
      status: "ready";
      columns: string[];
      sourceRows: string[][];
      rowStore: CsvRowStore;
    }
  | {
      status: "empty";
      columns: string[];
      sourceRows: string[][];
      rowStore: CsvRowStore;
    }
  | {
      status: "error";
      columns: string[];
      sourceRows: string[][];
      rowStore: CsvRowStore;
      error: unknown;
    };

export function readyCsvState(
  columns: string[],
  sourceRows: string[][],
): CsvResourceState {
  const rowStore = createCsvRowStoreFromRows(sourceRows);
  return sourceRows.length === 0
    ? { status: "empty", columns, sourceRows, rowStore }
    : { status: "ready", columns, sourceRows, rowStore };
}

export function useCsvResourceState({
  source,
  resource,
  dialect,
  retryVersion = 0,
}: CsvResourceInput & {
  dialect: CsvDialect;
  retryVersion?: number;
}): CsvResourceState {
  const content = resource?.content ?? null;
  const { delimiter, hasHeader } = dialect;
  const csvDialect = React.useMemo(
    () => ({ delimiter, hasHeader }),
    [delimiter, hasHeader],
  );
  const tableSource = source?.kind === "table" ? source : null;
  const textSource = source?.kind === "text" ? source : null;
  const csvResource = React.useMemo<CsvResource>(() => {
    if (tableSource) {
      return resolveCsvResource({ source: tableSource });
    }
    if (textSource) {
      return { kind: "text", text: textSource.text };
    }
    if (!content) {
      return { kind: "empty" };
    }
    if (content.payload.kind === "text") {
      return { kind: "text", text: content.payload.text };
    }
    return { kind: "resource", content };
  }, [tableSource, textSource, content]);
  const syncState = React.useMemo<CsvResourceState | null>(() => {
    if (csvResource.kind === "table") {
      return readyCsvState(csvResource.table.columns, csvResource.table.rows);
    }
    if (csvResource.kind === "text") {
      if (csvResource.text.length > SYNC_TEXT_PARSE_MAX_BYTES) return null;
      const table = parseCsv(csvResource.text, csvDialect);
      return readyCsvState(table.columns, table.rows);
    }
    if (csvResource.kind === "empty") {
      return {
        status: "idle",
        columns: [],
        sourceRows: [],
        rowStore: emptyCsvRowStore(),
      };
    }
    return null;
  }, [csvResource, csvDialect]);

  const [state, setState] = React.useState<CsvResourceState>({
    status: "idle",
    columns: [],
    sourceRows: [],
    rowStore: emptyCsvRowStore(),
  });

  const resourceEffectKey =
    syncState ||
    (csvResource.kind !== "resource" && csvResource.kind !== "text")
      ? null
      : joinEffectKey(["csv-resource", csvResource, csvDialect, retryVersion]);
  useKeyedMountEffect(resourceEffectKey, () => {
    if (syncState) return;
    if (csvResource.kind !== "resource" && csvResource.kind !== "text") return;

    const controller = new AbortController();
    const rowStore = createMutableCsvRowStore();
    let columns: string[] = [];
    let cancelled = false;
    setState({
      status: "loading",
      columns: [],
      sourceRows: [],
      rowStore: rowStore.snapshot(),
    });

    const onColumns = (next: string[]) => {
      if (cancelled) return;
      columns = next;
      rowStore.padRowsToColumnCount(columns.length);
      setState({
        status: "loading",
        columns,
        sourceRows: [],
        rowStore: rowStore.snapshot(),
      });
    };

    const onSourceRows = (sourceRowBatch: string[][]) => {
      if (cancelled) return;
      rowStore.appendRows(sourceRowBatch);
      setState({
        status: "loading",
        columns,
        sourceRows: [],
        rowStore: rowStore.snapshot(),
      });
    };

    const onDone = () => {
      if (cancelled) return;
      setState(readyCsvState(columns, rowStore.materializeRows()));
    };

    const onError = (error: unknown) => {
      if (cancelled || controller.signal.aborted) return;
      const sourceRows = rowStore.materializeRows();
      setState({
        status: "error",
        columns,
        sourceRows,
        rowStore: createCsvRowStoreFromRows(sourceRows),
        error: toCsvPreviewError(error),
      });
    };

    const runMainThread = (input: CsvStreamSource) => {
      void streamCsv(
        input,
        { onColumns, onRows: onSourceRows, onDone, onError },
        {
          delimiter: csvDialect.delimiter,
          hasHeader: csvDialect.hasHeader,
          batchSize: CSV_STREAM_BATCH_SIZE,
          signal: controller.signal,
        },
      );
    };

    const runResource = async () => {
      try {
        if (csvResource.kind === "text") {
          const textBlob = new Blob([csvResource.text], { type: "text/csv" });
          if (typeof Worker !== "undefined") {
            void parseCsvInWorker({
              source: textBlob,
              dialect: csvDialect,
              batchSize: CSV_STREAM_BATCH_SIZE,
              onColumns,
              onSourceRows,
              signal: controller.signal,
            }).then(onDone, (error) => {
              if (error instanceof CsvWorkerUnavailableError) {
                runMainThread(csvResource.text);
              } else {
                onError(error);
              }
            });
            return;
          }

          runMainThread(csvResource.text);
          return;
        }

        if (csvResource.content.payload.kind === "blob") {
          const { blob } = csvResource.content.payload;
          if (typeof Worker !== "undefined") {
            void parseCsvInWorker({
              source: blob,
              dialect: csvDialect,
              batchSize: CSV_STREAM_BATCH_SIZE,
              onColumns,
              onSourceRows,
              signal: controller.signal,
            }).then(onDone, (error) => {
              if (error instanceof CsvWorkerUnavailableError) {
                runMainThread(blob);
              } else {
                onError(error);
              }
            });
            return;
          }

          runMainThread(blob);
          return;
        }

        if (
          csvResource.content.payload.kind === "url" &&
          typeof Worker !== "undefined"
        ) {
          void csvResource.content
            .readBlob({ cache: "no-store", signal: controller.signal })
            .then((blob) =>
              parseCsvInWorker({
                source: blob,
                dialect: csvDialect,
                batchSize: CSV_STREAM_BATCH_SIZE,
                onColumns,
                onSourceRows,
                signal: controller.signal,
              }),
            )
            .then(onDone, (error) => {
              if (error instanceof CsvWorkerUnavailableError) {
                void runResourceStream();
              } else {
                onError(error);
              }
            });
          return;
        }

        await runResourceStream();
      } catch (error) {
        onError(error);
      }
    };

    const runResourceStream = async () => {
      if (csvResource.kind !== "resource") return;
      try {
        const cache =
          csvResource.content.payload.kind === "url" ? "no-store" : undefined;
        runMainThread(
          await csvResource.content.readStream(
            cache
              ? { cache, signal: controller.signal }
              : { signal: controller.signal },
          ),
        );
      } catch (error) {
        onError(error);
      }
    };

    void runResource();

    return () => {
      cancelled = true;
      controller.abort();
    };
  });

  return syncState ?? state;
}

function toCsvPreviewError(error: unknown): Error {
  if (isResourceError(error)) return error;
  if (isAbortError(error)) {
    return new ResourceError({
      kind: "aborted",
      message: "Loading was cancelled.",
      cause: error,
    });
  }
  return toCsvFormatError(error);
}

"use client";

import * as React from "react";
import { createPortal } from "react-dom";

import { useMountEffect } from "@/hooks/use-mount-effect";

export function stripHasRules(owner: CSSStyleSheet | CSSGroupingRule) {
  const rules = owner.cssRules;
  if (!rules) return;
  for (let index = rules.length - 1; index >= 0; index--) {
    const rule = rules[index];
    if ((rule as CSSStyleRule).selectorText?.includes(":has(")) {
      try {
        owner.deleteRule(index);
      } catch {
        // Ignore rules that cannot be removed.
      }
    } else if ((rule as CSSGroupingRule).cssRules?.length) {
      stripHasRules(rule as CSSGroupingRule);
    }
  }
}

let sharedSheets: CSSStyleSheet[] | null = null;
function getSharedSheets(): CSSStyleSheet[] {
  if (sharedSheets) return sharedSheets;
  const sheets: CSSStyleSheet[] = [];
  for (const sheet of Array.from(document.styleSheets)) {
    let rules: CSSRuleList;
    try {
      rules = sheet.cssRules;
    } catch {
      continue;
    }
    let text = "";
    for (const rule of Array.from(rules)) text += rule.cssText + "\n";
    try {
      const clone = new CSSStyleSheet();
      clone.replaceSync(text);
      stripHasRules(clone);
      sheets.push(clone);
    } catch {
      // Skip stylesheets that cannot be reconstructed.
    }
  }
  sharedSheets = sheets;
  return sheets;
}

function ShadowScope({
  className,
  style,
  children,
}: {
  className?: string;
  style?: React.CSSProperties;
  children: React.ReactNode;
}) {
  const hostRef = React.useRef<HTMLDivElement>(null);
  const [root, setRoot] = React.useState<ShadowRoot | null>(null);

  useMountEffect(() => {
    const host = hostRef.current;
    if (!host) return;
    const shadowRoot = host.shadowRoot ?? host.attachShadow({ mode: "open" });
    try {
      shadowRoot.adoptedStyleSheets = getSharedSheets();
    } catch {
      for (const node of Array.from(
        document.querySelectorAll('style, link[rel="stylesheet"]'),
      )) {
        try {
          shadowRoot.appendChild(node.cloneNode(true));
        } catch {
          // Ignore nodes that cannot be cloned.
        }
      }
    }
    setRoot(shadowRoot);
  });

  return (
    <div ref={hostRef} className={className} style={style}>
      {root ? createPortal(children, root) : null}
    </div>
  );
}

export function CsvStyleScope({
  isolate,
  className,
  style,
  children,
}: {
  isolate: boolean;
  className?: string;
  style?: React.CSSProperties;
  children: React.ReactNode;
}) {
  if (isolate) {
    return (
      <ShadowScope className={className} style={style}>
        {children}
      </ShadowScope>
    );
  }
  return (
    <div className={className} style={style}>
      {children}
    </div>
  );
}

