import {
  isViewerFormatError,
  ViewerFormatError,
  type ViewerFormatErrorMapperOptions,
} from "@/lib/viewer-errors";

export class CsvWorkerUnavailableError extends Error {
  constructor(message = "CSV worker unavailable", options?: ErrorOptions) {
    super(message, options);
    this.name = "CsvWorkerUnavailableError";
  }
}

export function toCsvFormatError(
  error: unknown,
  options: ViewerFormatErrorMapperOptions = {
    kind: "parse_failed",
    message: "Failed to parse CSV.",
  },
): ViewerFormatError {
  if (isViewerFormatError(error)) return error;
  return new ViewerFormatError({
    format: "csv",
    kind: options.kind,
    message: options.message,
    cause: error,
  });
}

export interface CsvWorkerRequest {
  parseRequestId: string;
  source: Blob;
  dialect: CsvDialect;
  batchSize: number;
}

export type CsvWorkerResponse =
  | { type: "columns"; parseRequestId: string; columns: string[] }
  | { type: "sourceRows"; parseRequestId: string; sourceRows: string[][] }
  | { type: "done"; parseRequestId: string }
  | { type: "error"; parseRequestId: string; message: string };

export function createCsvWorker(): Worker {
  return new Worker(new URL("./csv-viewer.worker.ts", import.meta.url), {
    type: "module",
  });
}

export function parseCsvInWorker({
  source,
  dialect,
  batchSize,
  onColumns,
  onSourceRows,
  signal,
}: {
  source: Blob;
  dialect: CsvDialect;
  batchSize: number;
  onColumns: (columns: string[]) => void;
  onSourceRows: (sourceRows: string[][]) => void;
  signal: AbortSignal;
}): Promise<void> {
  return new Promise((resolve, reject) => {
    let worker: Worker;
    try {
      worker = createCsvWorker();
    } catch (error) {
      reject(
        new CsvWorkerUnavailableError("CSV worker unavailable", {
          cause: error,
        }),
      );
      return;
    }

    const parseRequestId = crypto.randomUUID();
    const cleanup = () => {
      signal.removeEventListener("abort", abort);
      worker.terminate();
    };
    const abort = () => {
      cleanup();
      reject(new DOMException("Aborted", "AbortError"));
    };

    signal.addEventListener("abort", abort, { once: true });
    worker.onerror = (event) => {
      cleanup();
      reject(
        toCsvFormatError(event, {
          kind: "worker_failed",
          message: event?.message || "CSV worker failed.",
        }),
      );
    };
    worker.onmessage = (event: MessageEvent<CsvWorkerResponse>) => {
      const message = event.data;
      if (message.parseRequestId !== parseRequestId) return;
      if (message.type === "columns") onColumns(message.columns);
      else if (message.type === "sourceRows") onSourceRows(message.sourceRows);
      else if (message.type === "done") {
        cleanup();
        resolve();
      } else {
        cleanup();
        reject(
          toCsvFormatError(undefined, {
            kind: "parse_failed",
            message: message.message || "Failed to parse CSV.",
          }),
        );
      }
    };

    const request: CsvWorkerRequest = {
      parseRequestId,
      source,
      dialect,
      batchSize,
    };
    worker.postMessage(request);
  });
}

import {
  createCsvNormalizer,
  createCsvParser,
  padRowsToColumnCount,
  type CsvDialect,
} from "@/lib/csv";

import type { CsvWorkerRequest, CsvWorkerResponse } from "./csv-viewer-worker";

function post(message: CsvWorkerResponse) {
  self.postMessage(message);
}

async function* readWorkerTextChunks(source: Blob): AsyncGenerator<string> {
  const reader = source.stream().getReader();
  const decoder = new TextDecoder();
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      if (value) {
        const text = decoder.decode(value, { stream: true });
        if (text) yield text;
      }
    }
    const rest = decoder.decode();
    if (rest) yield rest;
  } finally {
    reader.releaseLock();
  }
}

async function parseInWorker({
  parseRequestId,
  source,
  dialect,
  batchSize,
}: CsvWorkerRequest) {
  const parser = createCsvParser({ delimiter: dialect.delimiter });
  const normalizer = createCsvNormalizer({ hasHeader: dialect.hasHeader });
  let sourceRowBatch: string[][] = [];

  const handleRecords = (records: string[][]) => {
    for (const record of records) {
      for (const event of normalizer.accept(record)) {
        if (event.type === "columns") {
          padRowsToColumnCount(sourceRowBatch, event.columns.length);
          post({ type: "columns", parseRequestId, columns: event.columns });
        } else {
          sourceRowBatch.push(event.row);
        }
      }
      if (sourceRowBatch.length >= batchSize) {
        post({
          type: "sourceRows",
          parseRequestId,
          sourceRows: sourceRowBatch,
        });
        sourceRowBatch = [];
      }
    }
  };

  for await (const chunk of readWorkerTextChunks(source)) {
    handleRecords(parser.push(chunk));
  }
  handleRecords(parser.flush());
  if (sourceRowBatch.length) {
    post({
      type: "sourceRows",
      parseRequestId,
      sourceRows: sourceRowBatch,
    });
  }
  post({ type: "done", parseRequestId });
}

self.onmessage = (event: MessageEvent<CsvWorkerRequest>) => {
  void parseInWorker(event.data).catch((error) => {
    const message = error instanceof Error ? error.message : String(error);
    post({
      type: "error",
      parseRequestId: event.data.parseRequestId,
      message,
    });
  });
};

"use client";

import * as React from "react";
import { Download } from "lucide-react";

import { cn } from "@/lib/utils";
import {
  ViewerDownloadError,
  type ViewerDownloadAction,
  type ViewerDownloadPayload,
} from "@/lib/viewer-download-actions";

import { Spinner } from "@/components/ui/spinner";

import { Button, buttonVariants } from "./button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "./dropdown-menu";
import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { joinEffectKey } from "@/lib/effect-key";

export interface TriggerViewerDownloadOptions {
  signal?: AbortSignal;
}

export async function triggerViewerDownload(
  action: ViewerDownloadAction,
  options?: TriggerViewerDownloadOptions,
): Promise<void> {
  if (action.isDisabled) {
    throw new ViewerDownloadError({
      actionId: action.id,
      kind: "disabled",
      message: "This download is disabled.",
    });
  }

  let payload: ViewerDownloadPayload;
  try {
    payload = await action.getPayload(options);
  } catch (error) {
    if (isAbortError(error)) {
      throw new ViewerDownloadError({
        actionId: action.id,
        kind: "aborted",
        message: "Download was cancelled.",
        cause: error,
      });
    }
    throw new ViewerDownloadError({
      actionId: action.id,
      kind: "payload_failed",
      message: "Could not prepare this download.",
      cause: error,
    });
  }

  if (payload.kind === "none") return;
  if (payload.kind === "href") {
    try {
      clickDownload(payload.href, action.fileName);
    } catch (error) {
      throw new ViewerDownloadError({
        actionId: action.id,
        kind: "unsupported",
        message: "Could not start this download.",
        cause: error,
      });
    }
    return;
  }

  try {
    const blob =
      payload.kind === "blob"
        ? payload.blob
        : new Blob([payload.text], {
            type: payload.mimeType ?? "text/plain;charset=utf-8",
          });
    const url = URL.createObjectURL(blob);
    try {
      clickDownload(url, action.fileName);
    } finally {
      URL.revokeObjectURL(url);
    }
  } catch (error) {
    throw new ViewerDownloadError({
      actionId: action.id,
      kind: "unsupported",
      message: "Could not start this download.",
      cause: error,
    });
  }
}

export type ViewerDownloadErrorHandler = (
  error: ViewerDownloadError,
  action: ViewerDownloadAction,
) => void;

export interface ViewerDownloadTrigger {
  pendingActionId: string | null;
  triggerDownload: (action: ViewerDownloadAction) => void;
}

export interface ViewerDownloadTriggerOptions {
  /** Reports non-aborted action failures; visible failure UI belongs to consumers. */
  onError?: ViewerDownloadErrorHandler;
  resetKey?: unknown;
}

export interface ViewerDownloadControlProps {
  actions: Array<ViewerDownloadAction | null | undefined>;
  variant?: React.ComponentProps<typeof Button>["variant"];
  size?: React.ComponentProps<typeof Button>["size"];
  className?: string;
  showLabel?: boolean;
  /** Reports non-aborted action failures; visible failure UI belongs to consumers. */
  onError?: ViewerDownloadErrorHandler;
}

export interface ViewerDownloadButtonProps
  extends Omit<ViewerDownloadControlProps, "actions"> {
  action: ViewerDownloadAction | null;
}

export interface ViewerDownloadMenuProps
  extends Omit<ViewerDownloadControlProps, "actions"> {
  actions: ViewerDownloadAction[];
}

export function useViewerDownloadHref(
  action: ViewerDownloadAction | null,
): string | null {
  const shouldCreateHref = action?.origin !== "derived";
  const payload = shouldCreateHref ? getSynchronousPayload(action) : null;

  return shouldCreateHref && payload?.kind === "href" ? payload.href : null;
}

export function useViewerDownloadTrigger({
  onError,
  resetKey = "",
}: ViewerDownloadTriggerOptions = {}): ViewerDownloadTrigger {
  const [pendingActionId, setPendingActionId] = React.useState<string | null>(
    null,
  );
  const abortControllerRef = React.useRef<AbortController | null>(null);

  useKeyedMountEffect(joinEffectKey([resetKey]), () => {
    return () => {
      abortControllerRef.current?.abort();
      abortControllerRef.current = null;
    };
  });

  const triggerDownload = React.useCallback(
    (action: ViewerDownloadAction) => {
      abortControllerRef.current?.abort();
      const abortController = new AbortController();
      abortControllerRef.current = abortController;
      setPendingActionId(action.id);
      void triggerViewerDownload(action, { signal: abortController.signal })
        .catch((error) => {
          reportDownloadError(error, action, onError);
        })
        .finally(() => {
          if (abortControllerRef.current === abortController) {
            abortControllerRef.current = null;
            setPendingActionId(null);
          }
        });
    },
    [onError],
  );

  return { pendingActionId, triggerDownload };
}

export function ViewerDownloadControl({
  actions,
  variant = "ghost",
  size = "iconSm",
  className = "size-7",
  showLabel = false,
  onError,
}: ViewerDownloadControlProps) {
  const enabledActions = actions.filter(
    (action): action is ViewerDownloadAction => Boolean(action),
  );

  if (enabledActions.length <= 1) {
    return (
      <ViewerDownloadButton
        action={enabledActions[0] ?? null}
        variant={variant}
        size={size}
        className={className}
        showLabel={showLabel}
        onError={onError}
      />
    );
  }

  return (
    <ViewerDownloadMenu
      actions={enabledActions}
      variant={variant}
      size={size}
      className={className}
      showLabel={showLabel}
      onError={onError}
    />
  );
}

export function ViewerDownloadButton({
  action,
  variant = "ghost",
  size = "iconSm",
  className = "size-7",
  showLabel = false,
  onError,
}: ViewerDownloadButtonProps) {
  const href = useViewerDownloadHref(action);
  const label = action?.label ?? "Download";
  const disabled = !action || action.isDisabled;
  const hasDownloadHref = Boolean(href);
  const { pendingActionId, triggerDownload } = useViewerDownloadTrigger({
    onError,
    resetKey: action,
  });
  const isPending = Boolean(action && pendingActionId === action.id);

  const handleClick = React.useCallback(() => {
    if (!action || hasDownloadHref) return;
    triggerDownload(action);
  }, [action, hasDownloadHref, triggerDownload]);

  if (href) {
    return (
      <a
        href={href}
        download={action?.fileName}
        className={cn(buttonVariants({ variant, size }), className)}
        aria-label={label}
        title={label}
        data-slot="button"
      >
        <Download className={showLabel ? "mr-1.5 size-4" : undefined} />
        {showLabel ? label : null}
      </a>
    );
  }

  return (
    <Button
      variant={variant}
      size={size}
      className={className}
      aria-label={label}
      title={label}
      disabled={disabled || isPending}
      onClick={handleClick}
    >
      {isPending ? (
        <Spinner className="size-4 animate-spin" />
      ) : (
        <Download className={showLabel ? "mr-1.5 size-4" : undefined} />
      )}
      {showLabel ? label : null}
    </Button>
  );
}

export function ViewerDownloadMenu({
  actions,
  variant = "ghost",
  size = "iconSm",
  className = "size-7",
  showLabel = false,
  onError,
}: ViewerDownloadMenuProps) {
  const actionSetKey = actions.map((action) => action.id).join("\u0000");
  const label = "Download";
  const { pendingActionId, triggerDownload } = useViewerDownloadTrigger({
    onError,
    resetKey: actionSetKey,
  });

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button
          variant={variant}
          size={size}
          className={className}
          aria-label={label}
          title={label}
          disabled={pendingActionId != null}
        >
          {pendingActionId != null ? (
            <Spinner className="size-4 animate-spin" />
          ) : (
            <Download className={showLabel ? "mr-1.5 size-4" : undefined} />
          )}
          {showLabel ? label : null}
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end">
        {actions.map((action) => (
          <DropdownMenuItem
            key={action.id}
            disabled={action.isDisabled || pendingActionId != null}
            onClick={() => triggerDownload(action)}
          >
            <Download />
            <span>{action.label}</span>
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

function clickDownload(href: string, fileName: string) {
  const anchor = document.createElement("a");
  anchor.href = href;
  anchor.download = fileName;
  anchor.rel = "noreferrer";
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
}

function getSynchronousPayload(
  action: ViewerDownloadAction | null,
): ViewerDownloadPayload | null {
  if (!action || action.isDisabled) return null;
  const payload = action.getPayload();
  return payload instanceof Promise ? null : payload;
}

function reportDownloadError(
  error: unknown,
  action: ViewerDownloadAction,
  onError: ViewerDownloadErrorHandler | undefined,
) {
  if (!(error instanceof ViewerDownloadError)) return;
  if (error.kind === "aborted") return;
  onError?.(error, action);
}

function isAbortError(error: unknown) {
  return error instanceof DOMException && error.name === "AbortError";
}

"use client";

import * as React from "react";

import {
  getFixedGridInverseRowWindowStyles,
  type CssLength,
  type FixedGridInverseRowWindowGeometry,
} from "./fixed-grid-layout";

type FixedGridRowWindowElement = keyof React.JSX.IntrinsicElements;
type FixedGridRowWindowElementProps = React.HTMLAttributes<HTMLElement> & {
  "data-slot"?: string;
};

export interface FixedGridRowWindowProps extends Omit<
  FixedGridRowWindowElementProps,
  "children"
> {
  as?: FixedGridRowWindowElement;
  children?: React.ReactNode;
  minWidth?: CssLength;
  offsetAs?: FixedGridRowWindowElement;
  offsetClassName?: string;
  offsetDataSlot?: string;
  offsetProps?: FixedGridRowWindowElementProps;
  rowMinWidth?: CssLength;
  rowOffsetRef?: React.Ref<HTMLElement>;
  rowWindowRef?: React.Ref<HTMLElement>;
  totalSize: CssLength;
  viewportHeight: number;
  virtualRowWindow: FixedGridInverseRowWindowGeometry;
  windowAs?: FixedGridRowWindowElement;
  windowClassName?: string;
  windowDataSlot?: string;
  windowProps?: FixedGridRowWindowElementProps;
}

export function FixedGridRowWindow({
  as = "div",
  children,
  minWidth,
  offsetAs = "div",
  offsetClassName,
  offsetDataSlot,
  offsetProps,
  rowMinWidth,
  rowOffsetRef,
  rowWindowRef,
  style,
  totalSize,
  viewportHeight,
  virtualRowWindow,
  windowAs = "div",
  windowClassName,
  windowDataSlot,
  windowProps,
  className,
  ...props
}: FixedGridRowWindowProps) {
  const { offsetStyle, spacerStyle, windowStyle } =
    getFixedGridInverseRowWindowStyles({
      minWidth,
      rowMinWidth,
      totalSize,
      viewportHeight,
      window: virtualRowWindow,
    });
  const offsetElementProps = {
    ...offsetProps,
    ...(offsetDataSlot ? { "data-slot": offsetDataSlot } : null),
    "aria-hidden": offsetProps?.["aria-hidden"] ?? true,
    className: offsetClassName ?? offsetProps?.className,
    ref: rowOffsetRef,
    style: { ...offsetProps?.style, ...offsetStyle },
  };
  const windowElementProps = {
    ...windowProps,
    ...(windowDataSlot ? { "data-slot": windowDataSlot } : null),
    className: windowClassName ?? windowProps?.className,
    ref: rowWindowRef,
    style: { ...windowProps?.style, ...windowStyle },
  };

  return React.createElement(
    as,
    {
      ...props,
      className,
      style: { ...style, ...spacerStyle },
    },
    React.createElement(offsetAs, offsetElementProps),
    React.createElement(windowAs, windowElementProps, children),
  );
}

"use client";

import * as React from "react";

import { useKeyedLayoutEffect } from "@/hooks/use-keyed-layout-effect";
import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { joinEffectKey } from "@/lib/effect-key";

export interface FixedGridNativeFindCellAddress {
  rowIndex: number;
  columnIndex: number;
}

export interface FixedGridNativeFindChunk {
  startRowIndex: number;
  endRowIndex: number;
  text: string;
}

interface FixedGridNativeFindBuild {
  chunks: FixedGridNativeFindChunk[];
  indexedCellCount: number;
}

type FixedGridNativeFindIdleWindow = Window &
  typeof globalThis & {
    cancelIdleCallback?: Window["cancelIdleCallback"];
    requestIdleCallback?: Window["requestIdleCallback"];
  };

const DEFAULT_MAX_CELLS_PER_CHUNK = 512;
const DEFAULT_MAX_INDEXED_CELLS = 250_000;
const NATIVE_FIND_IDLE_TIMEOUT_MS = 400;
const NATIVE_FIND_FALLBACK_DELAY_MS = 80;

export function FixedGridNativeFindIndex({
  rowCount,
  columnCount,
  getCellText,
  onCellMatch,
  dataSlot,
  enabled = true,
  maxCellsPerChunk = DEFAULT_MAX_CELLS_PER_CHUNK,
  maxIndexedCells = DEFAULT_MAX_INDEXED_CELLS,
}: {
  rowCount: number;
  columnCount: number;
  getCellText: (rowIndex: number, columnIndex: number) => string;
  onCellMatch: (cell: FixedGridNativeFindCellAddress) => void;
  dataSlot: string;
  enabled?: boolean;
  maxCellsPerChunk?: number;
  maxIndexedCells?: number;
}) {
  const [isReady, setIsReady] = React.useState(false);

  useKeyedMountEffect(
    joinEffectKey([
      "fixed-grid-native-find-ready",
      enabled,
      rowCount,
      columnCount,
      getCellText,
      maxCellsPerChunk,
      maxIndexedCells,
    ]),
    () => {
      setIsReady(false);
      if (
        !enabled ||
        !canBuildFixedGridNativeFindIndex({
          rowCount,
          columnCount,
          maxIndexedCells,
        })
      ) {
        return;
      }
      if (typeof window === "undefined") return;

      const show = () => setIsReady(true);
      const browserWindow = window as FixedGridNativeFindIdleWindow;
      if (
        browserWindow.requestIdleCallback &&
        browserWindow.cancelIdleCallback
      ) {
        const idleId = browserWindow.requestIdleCallback(show, {
          timeout: NATIVE_FIND_IDLE_TIMEOUT_MS,
        });
        return () => browserWindow.cancelIdleCallback?.(idleId);
      }

      const timeoutId = browserWindow.setTimeout(
        show,
        NATIVE_FIND_FALLBACK_DELAY_MS,
      );
      return () => browserWindow.clearTimeout(timeoutId);
    },
  );

  const index = React.useMemo<FixedGridNativeFindBuild | null>(() => {
    if (!enabled || !isReady) return null;
    return buildFixedGridNativeFindIndex({
      rowCount,
      columnCount,
      getCellText,
      maxCellsPerChunk,
      maxIndexedCells,
    });
  }, [
    columnCount,
    enabled,
    getCellText,
    isReady,
    maxCellsPerChunk,
    maxIndexedCells,
    rowCount,
  ]);

  if (!index || index.chunks.length === 0) return null;

  return (
    <div
      aria-hidden="true"
      className="pointer-events-none h-0 w-0 overflow-hidden opacity-0"
      data-native-find-indexed-cells={index.indexedCellCount}
      data-native-find-indexed-chunks={index.chunks.length}
      data-native-find-indexed-columns={normalizeNativeFindCount(columnCount)}
      data-native-find-indexed-rows={normalizeNativeFindCount(rowCount)}
      data-slot={dataSlot}
    >
      {index.chunks.map((chunk) => (
        <FixedGridNativeFindEntry
          key={chunk.startRowIndex}
          chunk={chunk}
          columnCount={columnCount}
          getCellText={getCellText}
          onCellMatch={onCellMatch}
        />
      ))}
    </div>
  );
}

function FixedGridNativeFindEntry({
  chunk,
  columnCount,
  getCellText,
  onCellMatch,
}: {
  chunk: FixedGridNativeFindChunk;
  columnCount: number;
  getCellText: (rowIndex: number, columnIndex: number) => string;
  onCellMatch: (cell: FixedGridNativeFindCellAddress) => void;
}) {
  const ref = React.useRef<HTMLSpanElement | null>(null);

  useKeyedLayoutEffect(
    joinEffectKey([
      "fixed-grid-native-find-entry",
      chunk.startRowIndex,
      chunk.endRowIndex,
      chunk.text,
      columnCount,
      getCellText,
      onCellMatch,
    ]),
    () => {
      const element = ref.current;
      if (!element) return;
      element.setAttribute("hidden", "until-found");

      const scrollToSelectedCell = () => {
        onCellMatch(
          resolveFixedGridNativeFindCell({
            chunk,
            columnCount,
            getCellText,
            offset: selectedTextOffsetIn(element),
          }),
        );
      };

      const handleBeforeMatch = () => {
        scrollToSelectedCell();
        if (typeof requestAnimationFrame === "function") {
          requestAnimationFrame(() => {
            scrollToSelectedCell();
            element.setAttribute("hidden", "until-found");
          });
          return;
        }
        element.setAttribute("hidden", "until-found");
      };

      element.addEventListener("beforematch", handleBeforeMatch);
      return () => {
        element.removeEventListener("beforematch", handleBeforeMatch);
      };
    },
  );

  return (
    <span
      ref={ref}
      className="block h-px w-px overflow-hidden whitespace-pre"
      data-native-find-end-row={chunk.endRowIndex}
      data-native-find-start-row={chunk.startRowIndex}
    >
      {chunk.text || " "}
    </span>
  );
}

export function buildFixedGridNativeFindIndex({
  rowCount,
  columnCount,
  getCellText,
  maxCellsPerChunk = DEFAULT_MAX_CELLS_PER_CHUNK,
  maxIndexedCells = DEFAULT_MAX_INDEXED_CELLS,
}: {
  rowCount: number;
  columnCount: number;
  getCellText: (rowIndex: number, columnIndex: number) => string;
  maxCellsPerChunk?: number;
  maxIndexedCells?: number;
}): FixedGridNativeFindBuild | null {
  const safeRowCount = normalizeNativeFindCount(rowCount);
  const safeColumnCount = normalizeNativeFindCount(columnCount);
  if (safeRowCount === 0 || safeColumnCount === 0) {
    return { chunks: [], indexedCellCount: 0 };
  }

  const indexedCellCount = safeRowCount * safeColumnCount;
  if (!isNativeFindIndexedCellCountAllowed(indexedCellCount, maxIndexedCells)) {
    return null;
  }

  const rowsPerChunk = nativeFindRowsPerChunk({
    columnCount: safeColumnCount,
    maxCellsPerChunk,
  });
  const chunks: FixedGridNativeFindChunk[] = [];
  for (
    let startRowIndex = 0;
    startRowIndex < safeRowCount;
    startRowIndex += rowsPerChunk
  ) {
    const endRowIndex = Math.min(safeRowCount, startRowIndex + rowsPerChunk);
    chunks.push({
      startRowIndex,
      endRowIndex,
      text: fixedGridNativeFindChunkText({
        startRowIndex,
        endRowIndex,
        columnCount: safeColumnCount,
        getCellText,
      }),
    });
  }

  return { chunks, indexedCellCount };
}

function canBuildFixedGridNativeFindIndex({
  rowCount,
  columnCount,
  maxIndexedCells,
}: {
  rowCount: number;
  columnCount: number;
  maxIndexedCells: number;
}) {
  const safeRowCount = normalizeNativeFindCount(rowCount);
  const safeColumnCount = normalizeNativeFindCount(columnCount);
  if (safeRowCount === 0 || safeColumnCount === 0) return false;
  return isNativeFindIndexedCellCountAllowed(
    safeRowCount * safeColumnCount,
    maxIndexedCells,
  );
}

function isNativeFindIndexedCellCountAllowed(
  indexedCellCount: number,
  maxIndexedCells: number,
) {
  return (
    Number.isSafeInteger(indexedCellCount) &&
    indexedCellCount <= normalizeNativeFindCellLimit(maxIndexedCells)
  );
}

function fixedGridNativeFindChunkText({
  startRowIndex,
  endRowIndex,
  columnCount,
  getCellText,
}: {
  startRowIndex: number;
  endRowIndex: number;
  columnCount: number;
  getCellText: (rowIndex: number, columnIndex: number) => string;
}) {
  const parts: string[] = [];
  for (let rowIndex = startRowIndex; rowIndex < endRowIndex; rowIndex += 1) {
    for (let columnIndex = 0; columnIndex < columnCount; columnIndex += 1) {
      if (parts.length > 0) parts.push(columnIndex === 0 ? "\n" : "\t");
      parts.push(getCellText(rowIndex, columnIndex));
    }
  }
  return parts.join("");
}

function resolveFixedGridNativeFindCell({
  chunk,
  columnCount,
  getCellText,
  offset,
}: {
  chunk: FixedGridNativeFindChunk;
  columnCount: number;
  getCellText: (rowIndex: number, columnIndex: number) => string;
  offset: number | null;
}): FixedGridNativeFindCellAddress {
  if (offset == null || offset < 0) {
    return { rowIndex: chunk.startRowIndex, columnIndex: 0 };
  }

  let cursor = 0;
  for (
    let rowIndex = chunk.startRowIndex;
    rowIndex < chunk.endRowIndex;
    rowIndex += 1
  ) {
    for (let columnIndex = 0; columnIndex < columnCount; columnIndex += 1) {
      if (cursor > 0) cursor += 1;
      const text = getCellText(rowIndex, columnIndex);
      const cellStart = cursor;
      const cellEnd = cellStart + text.length;
      if (text.length > 0 && offset >= cellStart && offset <= cellEnd) {
        return { rowIndex, columnIndex };
      }
      cursor = cellEnd;
    }
  }

  return { rowIndex: chunk.startRowIndex, columnIndex: 0 };
}

function selectedTextOffsetIn(element: HTMLElement): number | null {
  const selection =
    element.ownerDocument.getSelection?.() ??
    (typeof window === "undefined" ? null : window.getSelection());
  if (!selection || selection.rangeCount === 0) return null;

  const selectedRange = selection.getRangeAt(0);
  if (!element.contains(selectedRange.startContainer)) return null;

  const prefixRange = element.ownerDocument.createRange();
  try {
    prefixRange.selectNodeContents(element);
    prefixRange.setEnd(selectedRange.startContainer, selectedRange.startOffset);
    return prefixRange.toString().length;
  } finally {
    prefixRange.detach();
  }
}

function nativeFindRowsPerChunk({
  columnCount,
  maxCellsPerChunk,
}: {
  columnCount: number;
  maxCellsPerChunk: number;
}) {
  const safeCellLimit = Math.max(
    1,
    normalizeNativeFindCellLimit(maxCellsPerChunk),
  );
  return Math.max(1, Math.min(128, Math.floor(safeCellLimit / columnCount)));
}

function normalizeNativeFindCount(value: number) {
  return Number.isSafeInteger(value) && value > 0 ? Math.floor(value) : 0;
}

function normalizeNativeFindCellLimit(value: number) {
  return Number.isSafeInteger(value) && value > 0 ? Math.floor(value) : 0;
}
